function clone(o){return JSON.parse(JSON.stringify(o))}
function toMin(t){const[h,m]=t.split(':').map(Number);return h*60+m}
function gapMin(a,b){return toMin(b)-toMin(a)}

/* ---------- STATE ---------- */
let DB = null;
let UI = { view:'dash', cls:null, teacher:null, expTab:'class', expTarget:null };
const STORE='esagrada_horarios_v3';
const DEFAULT_LOGO = './assets/default_logo.png';

/* Camada de armazenamento: funciona dentro do Claude (window.storage)
   E como ficheiro descarregado no computador (localStorage). */
async function storeSave(str){
  let ok=false;
  try{ if(window.storage&&window.storage.set){ await window.storage.set(STORE,str); ok=true; } }catch(e){}
  try{ localStorage.setItem(STORE,str); ok=true; }catch(e){}
  return ok;
}
async function storeLoad(){
  try{ if(window.storage&&window.storage.get){ const r=await window.storage.get(STORE); if(r&&r.value) return r.value; } }catch(e){}
  try{ const v=localStorage.getItem(STORE); if(v) return v; }catch(e){}
  return null;
}
let _lastSyncPullTs = 0;
let _isSyncing = false;

function getCloudSyncUrl() {
  if (typeof DB !== 'undefined' && DB.settings && DB.settings.syncUrl && DB.settings.syncUrl.trim()) {
    return DB.settings.syncUrl.trim();
  }
  return 'https://jsonblob.com/api/jsonBlob/019fc7b0-c91d-780a-ac37-6f48d6a840ec';
}

function setCloudStatus(st, msg) {
  window._cloudStatus = st;
  const els = document.querySelectorAll('.cloud-sync-badge');
  els.forEach(el => {
    if (st === 'ok') {
      el.style.background = '#e3f5ec';
      el.style.color = '#0e7d52';
      el.innerHTML = '☁️ Nuvem Sincronizada';
      el.title = 'Sincronização em tempo real ativa';
    } else if (st === 'syncing') {
      el.style.background = '#e8effb';
      el.style.color = '#2155b8';
      el.innerHTML = '⚡ Sincronizando...';
      el.title = 'Enviando/recebendo dados com a nuvem';
    } else {
      el.style.background = '#fff3cd';
      el.style.color = '#856404';
      el.innerHTML = msg ? `☁️ ${msg}` : '☁️ Erro na Sincronização';
      el.title = msg || 'Não foi possível ligar ao servidor de sincronização';
    }
  });
}

let _syncingTimeoutTimer = null;
let _pendingPushRequest = false;

function mergeById(localArr = [], remoteArr = [], maxLimit = 2000) {
  const map = new Map();
  (remoteArr || []).forEach(item => {
    if (item && item.id != null) map.set(String(item.id), item);
  });
  (localArr || []).forEach(item => {
    if (item && item.id != null) {
      const existing = map.get(String(item.id));
      if (!existing || (item.ts && existing.ts && item.ts >= existing.ts)) {
        map.set(String(item.id), item);
      }
    }
  });
  const merged = Array.from(map.values());
  merged.sort((a, b) => (b.ts || 0) - (a.ts || 0));
  return merged.slice(0, maxLimit);
}

async function syncPush(){
  if (!DB) return;
  if (_isSyncing) {
    _pendingPushRequest = true;
    return;
  }
  _isSyncing = true;
  _pendingPushRequest = false;
  
  clearTimeout(_syncingTimeoutTimer);
  _syncingTimeoutTimer = setTimeout(() => {
    _isSyncing = false;
    if (_pendingPushRequest) {
      _pendingPushRequest = false;
      syncPush();
    }
  }, 8000);

  try {
    setCloudStatus('syncing');
    const cloudUrl = getCloudSyncUrl();

    let remoteData = {};
    try {
      const getRes = await fetch(cloudUrl, { cache: 'no-store' });
      if (getRes.ok) remoteData = await getRes.json() || {};
    } catch(e){}

    const mergedAcessos = mergeById(DB.acessos || [], remoteData.acessos || [], 2000);
    const mergedDiario  = mergeById(DB.diario || [], remoteData.diario || [], 1000);
    const mergedAvisos  = mergeById(DB.avisos || [], remoteData.avisos || [], 500);

    if (mergedAcessos.length !== (DB.acessos || []).length || mergedDiario.length !== (DB.diario || []).length || mergedAvisos.length !== (DB.avisos || []).length) {
      DB.acessos = mergedAcessos;
      DB.diario = mergedDiario;
      DB.avisos = mergedAvisos;
      await storeSave(JSON.stringify(DB));
    }

    const payload = {
      acessos: mergedAcessos,
      diario: mergedDiario,
      avisos: mergedAvisos,
      deletedAvisos: Array.from(new Set([...(DB.deletedAvisos || []), ...(remoteData.deletedAvisos || [])])),
      ts: Date.now()
    };

    const putRes = await fetch(cloudUrl, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });

    if (putRes.ok) {
      _lastSyncPullTs = payload.ts;
      setCloudStatus('ok');
    } else {
      setCloudStatus('error', 'Falha Servidor (' + putRes.status + ')');
    }
  } catch(e) {
    console.warn('[CloudSync Push Error]', e);
    setCloudStatus('error', 'Sem Redes');
  } finally {
    clearTimeout(_syncingTimeoutTimer);
    _isSyncing = false;
    if (_pendingPushRequest) {
      _pendingPushRequest = false;
      setTimeout(syncPush, 150);
    }
  }
}

async function syncPull(){
  if (!DB || _isSyncing) return;
  _isSyncing = true;
  
  clearTimeout(_syncingTimeoutTimer);
  _syncingTimeoutTimer = setTimeout(() => {
    _isSyncing = false;
    if (_pendingPushRequest) {
      _pendingPushRequest = false;
      syncPush();
    }
  }, 8000);

  try {
    const cloudUrl = getCloudSyncUrl();
    const res = await fetch(cloudUrl, { cache: 'no-store' });
    if(!res.ok) {
      setCloudStatus('error', 'Erro (' + res.status + ')');
      _isSyncing = false;
      if (_pendingPushRequest) {
        _pendingPushRequest = false;
        setTimeout(syncPush, 100);
      }
      return;
    }
    const remote = await res.json();
    if(!remote || typeof remote !== 'object') {
      setCloudStatus('ok');
      _isSyncing = false;
      return;
    }

    let localNeedsPush = false;
    let localUpdated = false;

    if (Array.isArray(remote.acessos)) {
      if (!Array.isArray(DB.acessos)) DB.acessos = [];
      const localMap = new Map(DB.acessos.map(x => [String(x.id), x]));
      const remoteMap = new Map(remote.acessos.map(x => [String(x.id), x]));

      remote.acessos.forEach(rem => {
        if (rem && rem.id != null && !localMap.has(String(rem.id))) {
          DB.acessos.unshift(rem);
          localMap.set(String(rem.id), rem);
          localUpdated = true;
        }
      });

      DB.acessos.forEach(loc => {
        if (loc && loc.id != null && !remoteMap.has(String(loc.id))) {
          localNeedsPush = true;
        }
      });
    }

    if (Array.isArray(remote.diario)) {
      if (!Array.isArray(DB.diario)) DB.diario = [];
      const localDiarioMap = new Map(DB.diario.map(x => [String(x.id), x]));
      const remoteDiarioMap = new Map(remote.diario.map(x => [String(x.id), x]));

      remote.diario.forEach(rem => {
        if (rem && rem.id != null && !localDiarioMap.has(String(rem.id))) {
          DB.diario.unshift(rem);
          localDiarioMap.set(String(rem.id), rem);
          localUpdated = true;
        }
      });

      DB.diario.forEach(loc => {
        if (loc && loc.id != null && !remoteDiarioMap.has(String(loc.id))) {
          localNeedsPush = true;
        }
      });
    }

    if (Array.isArray(remote.avisos)) {
      if (!Array.isArray(DB.avisos)) DB.avisos = [];
      const localAvMap = new Map(DB.avisos.map(x => [String(x.id), x]));
      const remoteAvMap = new Map(remote.avisos.map(x => [String(x.id), x]));

      remote.avisos.forEach(rem => {
        if (rem && rem.id != null && !localAvMap.has(String(rem.id))) {
          DB.avisos.unshift(rem);
          localAvMap.set(String(rem.id), rem);
          localUpdated = true;
        }
      });

      DB.avisos.forEach(loc => {
        if (loc && loc.id != null && !remoteAvMap.has(String(loc.id))) {
          localNeedsPush = true;
        }
      });
    }

    _lastSyncPullTs = Math.max(_lastSyncPullTs, remote.ts || 0);

    if (localUpdated) {
      DB.acessos.sort((a,b) => (b.ts || 0) - (a.ts || 0));
      await storeSave(JSON.stringify(DB));
      setCloudStatus('ok');
      if (['portaria', 'avisos', 'dash', 'mural', 'analise', 'diario'].includes(UI.view)) {
        render();
      }
    } else {
      setCloudStatus('ok');
    }

    _isSyncing = false;
    clearTimeout(_syncingTimeoutTimer);

    if (localNeedsPush || _pendingPushRequest) {
      _pendingPushRequest = false;
      setTimeout(syncPush, 100);
    }
  } catch(e) {
    console.warn('[CloudSync Pull Error]', e);
    setCloudStatus('error', 'Sem Ligações');
    _isSyncing = false;
    clearTimeout(_syncingTimeoutTimer);
    if (_pendingPushRequest) {
      _pendingPushRequest = false;
      setTimeout(syncPush, 500);
    }
  }
}

async function testCloudSync() {
  const url = getCloudSyncUrl();
  try {
    if(typeof toast === 'function') toast('🔄 A testar conexão com a nuvem...');
    const res = await fetch(url, { cache: 'no-store' });
    if (res.ok) {
      if(typeof toast === 'function') toast('✅ Conexão à Nuvem estabelecida com sucesso!');
      syncPush();
    } else {
      if(typeof toast === 'function') toast('⚠️ Servidor respondeu com código ' + res.status, true);
    }
  } catch(e) {
    if(typeof toast === 'function') toast('❌ Erro de rede ao conectar com a Nuvem: ' + e.message, true);
  }
}

setInterval(syncPull, 3000);

async function persist(){
  setSave('saving');
  const ok=await storeSave(JSON.stringify(DB));
  setSave(ok?'ok':'local');
  scheduleBackup();
  syncPush();
}
async function loadDB(){
  const v=await storeLoad();
  if(v){ try{ return JSON.parse(v); }catch(e){} }
  return null;
}

/* ---------- BACKUP AUTOMÁTICO num ficheiro (File System Access) ----------
   Ideal: apontar para uma pasta do Google Drive para Desktop — o ficheiro
   é então sincronizado para a nuvem automaticamente. */
const FS_OK = (typeof window!=='undefined') && ('showSaveFilePicker' in window);
let backupHandle=null, backupName='', backupGranted=false, lastBackup=null, backupTimer=null;

function idbOpen(){ return new Promise((res,rej)=>{ try{ const r=indexedDB.open('esagrada_bk',1);
  r.onupgradeneeded=()=>r.result.createObjectStore('h'); r.onsuccess=()=>res(r.result); r.onerror=()=>rej(r.error);
}catch(e){ rej(e);} }); }
async function idbSet(k,v){ try{ const db=await idbOpen(); await new Promise((res,rej)=>{ const tx=db.transaction('h','readwrite'); tx.objectStore('h').put(v,k); tx.oncomplete=()=>res(); tx.onerror=()=>rej(tx.error);}); }catch(e){} }
async function idbGet(k){ try{ const db=await idbOpen(); return await new Promise((res)=>{ const tx=db.transaction('h','readonly'); const rq=tx.objectStore('h').get(k); rq.onsuccess=()=>res(rq.result); rq.onerror=()=>res(null);}); }catch(e){ return null; } }
async function idbDel(k){ try{ const db=await idbOpen(); await new Promise((res)=>{ const tx=db.transaction('h','readwrite'); tx.objectStore('h').delete(k); tx.oncomplete=()=>res(); tx.onerror=()=>res();}); }catch(e){} }

async function permState(h,write,ask){
  try{ const opt={mode:write?'readwrite':'read'};
    if(h.queryPermission && (await h.queryPermission(opt))==='granted') return true;
    if(ask && h.requestPermission && (await h.requestPermission(opt))==='granted') return true;
  }catch(e){}
  return false;
}
async function connectBackup(){
  if(!FS_OK){ toast('Este navegador não suporta ligação automática. Use Chrome/Edge ou a descarga .json.',true); return; }
  try{
    const h=await window.showSaveFilePicker({suggestedName:'esagrada-horarios.json',
      types:[{description:'Cópia de segurança Esagrada',accept:{'application/json':['.json']}}]});
    backupHandle=h; backupName=h.name; backupGranted=true; await idbSet('handle',h);
    await writeBackup(true);
    toast('Ficheiro de segurança ligado ✓');
    if(UI.view==='export') render();
  }catch(e){ if(e&&e.name!=='AbortError'){ console.error(e); toast('Não foi possível ligar o ficheiro',true);} }
}
async function disconnectBackup(){ backupHandle=null; backupName=''; backupGranted=false; await idbDel('handle'); toast('Ligação de segurança removida'); if(UI.view==='export') render(); }
async function writeBackup(ask){
  if(!backupHandle) return false;
  try{
    if(!(await permState(backupHandle,true,ask))){ backupGranted=false; const c=$('#bkStatus'); if(c)c.innerHTML=bkStatusHTML(); return false; }
    backupGranted=true;
    const w=await backupHandle.createWritable();
    await w.write(JSON.stringify(DB,null,2)); await w.close();
    lastBackup=new Date();
    const c=$('#bkStatus'); if(c) c.innerHTML=bkStatusHTML();
    return true;
  }catch(e){ console.error('backup write',e); return false; }
}
function scheduleBackup(){ if(!backupHandle) return; clearTimeout(backupTimer); backupTimer=setTimeout(()=>writeBackup(false),1200); }
async function restoreBackupHandle(){
  if(!FS_OK) return;
  const h=await idbGet('handle');
  if(h){ backupHandle=h; backupName=h.name||'cópia.json'; backupGranted=await permState(h,true,false); }
}
function fmtTime(d){ if(!d)return '—'; try{ return d.toLocaleString('pt-PT',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}); }catch(e){ return d.toLocaleString(); } }
function bkStatusHTML(){
  if(!backupHandle) return `<span class="dot" style="background:#c46a17"></span> Nenhum ficheiro automático ligado`;
  if(!backupGranted) return `<span class="dot" style="background:#d6a52e"></span> Ligado a <b>${esc(backupName)}</b> — clique em <b>Gravar agora</b> para reactivar a permissão`;
  return `<span class="dot" style="background:#0e7d52"></span> Ligado a <b>${esc(backupName)}</b> · última gravação: ${fmtTime(lastBackup)}`;
}
function setSave(s){
  const c=$('#saveChip'); if(!c)return;
  if(s==='saving'){c.innerHTML='<span class="dot" style="background:#d6a52e;box-shadow:0 0 0 3px rgba(214,165,46,.2)"></span>A guardar…';}
  else if(s==='local'){c.innerHTML='<span class="dot" style="background:#8a93a6"></span>Sessão';}
  else{c.innerHTML='<span class="dot"></span>Guardado';}
}

