function seed(){
  const cats=[
    {id:'tc',name:'CN-Tronco Comum',color:'#2155b8'},
    {id:'ce',name:'CN-Específico',color:'#0e7d52'},
    {id:'cp',name:'CN-Profissionalizante',color:'#6d3fb0'},
    {id:'ci',name:'C. Interno',color:'#c46a17'},
    {id:'ex',name:'Extracurricular',color:'#c0356a'},
  ];
  // ── Professores (dados reais 2026) ──
  const PROFS={
    101:'Edilson Arlindo Chissano',102:'Filipe João Majone',103:'Kyambesi Kabulo Felix',
    104:'Fausto Ghirardelli',105:'Luís Adelino Ngoca',106:'Marcelo da Glória Joaquim Bota Júnior',
    107:'Gabriel Zacarias Caetano',108:'Lencinio Zacarias Vilanculo',109:'Mércia Luciano Cuamba',
    110:'Milton Tomás Taela Guilima',111:'Tomás da Conceição Joanninha',112:'Daniel Zameia',
    113:'Salvado Mário Machava',114:'Pe Roberto Maver',115:'Cheila Francisco Naife',
    116:'Gaudêncio Aflito Carlota',117:'Jamisse Carlos Milice',118:'Armando Ricardo Henrique',
    119:'Milton Fanuel Guambe',120:'Celso Hilário Mutemba',
  };
  const teachers=Object.entries(PROFS).map(([pid,full])=>{
    let title='',name=full; if(/^Pe\s+/.test(full)){ title='Pe.'; name=full.replace(/^Pe\s+/,''); }
    return {id:'p'+pid,title,name,notes:'',unav:[]};
  });

  // ── Disciplinas (código → nome, categoria, professor) ──
  const DISC={
    PT:['Português','tc',101], ING:['Inglês','tc',102], FIL:['Filosofia','tc',114],
    IFIC:['Intr. à Filosofia','tc',114], MAT:['Matemática','tc',105], TICS:["TIC's",'tc',113],
    EDF:['Educação Física','tc',109], RET:['Reunião de Turma','tc',null],
    FRA:['Francês','ce',103], HIS:['História','ce',101], GEO:['Geografia','ce',112],
    QUI:['Química','ce',107], FIS:['Física','ce',106], BIO:['Biologia','ce',108],
    DGD:['Des. e Geom. Descritiva','ce',116],
    PSI:['Psicopedagogia','cp',110], AGRO:['Agro-pecuária','cp',108], NE:['Noções de Empreend.','cp',111],
    ETI:['Ética e Cidadania','ci',114], IINT:['Inglês Integral','ci',115], ITA:['Italiano','ci',104], INFAV:['Informática Avançada','ci',113],
    XCUR:['Extracurricular','ex',null],
  };
  const subjects=[]; const S={}; const DC={};
  Object.entries(DISC).forEach(([code,[name,cat,pid]])=>{
    let sid=S[name]; if(!sid){ sid=uid(); subjects.push({id:sid,name,catId:cat}); S[name]=sid; }
    DC[code]={sid,tid:pid?('p'+pid):null,name};
  });

  const classes=[
    {id:'10A',name:'10-1',type:'mista',groups:['A','B1','B2']},
    {id:'10B',name:'10-2',type:'pura', groups:[]},
    {id:'11', name:'11',  type:'mista',groups:['A','B1','B2']},
  ];

  // ── Horários reais (índice 0..7 → m1..m6,a1,a2). string=turma inteira; objecto=por secção ──
  const m=o=>o; // mista
  const h10A={
    SEGUNDA:[m({A:'FRA',B1:'FIS',B2:'FIS'}),m({A:'FRA',B1:'FIS',B2:'FIS'}),m({A:'MAT',B1:'MAT',B2:'MAT'}),m({A:'ING',B1:'ING',B2:'ING'}),m({A:'GEO',B1:'GEO',B2:'BIO'}),m({A:'GEO',B1:'GEO',B2:'BIO'}),'IINT','IINT'],
    'TERÇA':[m({A:'PT',B1:'PT',B2:'PT'}),m({A:'FIL',B1:'FIL',B2:'FIL'}),m({A:'PSI',B1:'FIS',B2:'FIS'}),m({A:'MAT',B1:'MAT',B2:'MAT'}),m({A:'FRA',B1:'QUI',B2:'QUI'}),m({A:'FRA',B1:'QUI',B2:'QUI'}),'XCUR','XCUR'],
    QUARTA:[m({A:'ING',B1:'ING',B2:'ING'}),m({A:'ING',B1:'ING',B2:'ING'}),m({A:'HIS',B1:'QUI',B2:'QUI'}),m({A:'HIS',B1:'QUI',B2:'QUI'}),m({A:'FIL',B1:'FIL',B2:'FIL'}),m({A:'RET',B1:'RET',B2:'RET'}),m({A:'ITA',B1:'INFAV',B2:'INFAV'}),m({A:'ITA',B1:'INFAV',B2:'INFAV'})],
    QUINTA:[m({A:'PT',B1:'PT',B2:'PT'}),m({A:'PT',B1:'PT',B2:'PT'}),m({A:'MAT',B1:'MAT',B2:'MAT'}),m({A:'MAT',B1:'MAT',B2:'MAT'}),m({A:'FIL',B1:'FIL',B2:'FIL'}),m({A:'ING',B1:'ING',B2:'ING'}),m({A:'NE',B1:'NE',B2:'NE'}),'XCUR'],
    SEXTA:[m({A:'PT',B1:'PT',B2:'PT'}),m({A:'PT',B1:'PT',B2:'PT'}),m({A:'MAT',B1:'MAT',B2:'MAT'}),m({A:'GEO',B1:'GEO',B2:'BIO'}),m({A:'HIS',B1:'FIS',B2:'FIS'}),m({A:'TICS',B1:'TICS',B2:'TICS'}),'EDF','EDF'],
  };
  const h10B={
    SEGUNDA:['PT','PT','ING','RET','BIO','BIO','EDF','EDF'],
    'TERÇA':['FIS','FIS','FIL','PT','ING','MAT','XCUR','XCUR'],
    QUARTA:['QUI','QUI','MAT','MAT','ING','ING','NE','IINT'],
    QUINTA:['FIS','FIS','PT','PT','TICS','FIL','IINT','XCUR'],
    SEXTA:['MAT','MAT','FIL','BIO','QUI','QUI','INFAV','INFAV'],
  };
  const h11={
    SEGUNDA:[m({A:'ING',B1:'ING',B2:'ING'}),m({A:'ING',B1:'ING',B2:'ING'}),m({A:'FRA',B1:'FIS',B2:'FIS'}),m({A:'MAT',B1:'FIS',B2:'FIS'}),m({A:'PT',B1:'PT',B2:'PT'}),m({A:'PT',B1:'PT',B2:'PT'}),m({A:'PSI',B1:'NE',B2:'AGRO'}),m({A:'PSI',B1:'NE',B2:'AGRO'})],
    'TERÇA':[m({A:'FRA',B1:'MAT',B2:'MAT'}),m({A:'FRA',B1:'MAT',B2:'MAT'}),m({A:'GEO',B1:'GEO',B2:'BIO'}),m({A:'GEO',B1:'GEO',B2:'BIO'}),m({A:'PT',B1:'PT',B2:'PT'}),m({A:'ING',B1:'ING',B2:'ING'}),'XCUR','XCUR'],
    QUARTA:[m({A:'PT',B1:'PT',B2:'PT'}),m({A:'PT',B1:'PT',B2:'PT'}),m({A:'ING',B1:'ING',B2:'ING'}),m({A:'ING',B1:'ING',B2:'ING'}),'TICS','TICS','EDF','EDF'],
    QUINTA:[m({A:'MAT',B1:'MAT',B2:'MAT'}),m({A:'MAT',B1:'MAT',B2:'MAT'}),m({A:'FRA',B1:'QUI',B2:'QUI'}),m({A:'FRA',B1:'QUI',B2:'QUI'}),m({A:'IFIC',B1:'IFIC',B2:'IFIC'}),m({A:'HIS',B1:'INFAV',B2:'INFAV'}),m({A:'ITA',B1:'INFAV',B2:'INFAV'}),'XCUR'],
    SEXTA:[m({A:'IFIC',B1:'IFIC',B2:'IFIC'}),m({A:'IFIC',B1:'IFIC',B2:'IFIC'}),m({A:'HIS',B1:'QUI',B2:'QUI'}),m({A:'HIS',B1:'FIS',B2:'FIS'}),m({A:'RET',B1:'RET',B2:'RET'}),m({A:'GEO',B1:'GEO',B2:'BIO'}),'IINT','IINT'],
  };
  const SLOTIDS=['m1','m2','m3','m4','m5','m6','a1','a2'];
  const mkE=(dc,grp)=>({id:uid(),sid:dc.sid,txt:'',grp:grp||'',tid:dc.tid||null,catId:null});
  function buildTT(sched){
    const out={}; DAYS.forEach(d=>out[d]={});
    DAYS.forEach(d=>{ const arr=sched[d]||[]; arr.forEach((cell,i)=>{ const slot=SLOTIDS[i]; if(!cell)return;
      let entries=[];
      if(typeof cell==='string'){ const dc=DC[cell]; if(dc) entries=[mkE(dc,'')]; }
      else { const secs=Object.keys(cell); const names=secs.map(s=>DC[cell[s]]?DC[cell[s]].name:cell[s]);
        if(names.every(n=>n===names[0])){ const dc=DC[cell[secs[0]]]; if(dc) entries=[mkE(dc,'')]; }
        else secs.forEach(s=>{ const dc=DC[cell[s]]; if(dc) entries.push(mkE(dc,s)); });
      }
      if(entries.length) out[d][slot]=entries;
    }); });
    return out;
  }
  const tt={ '10A':buildTT(h10A), '10B':buildTT(h10B), '11':buildTT(h11) };

  // ── Atribuições derivadas dos horários (horas por semana automáticas) ──
  const assignments=[];
  Object.keys(tt).forEach(cid=>{
    const map={};
    DAYS.forEach(d=>SLOTIDS.forEach(sid=>{ const a=tt[cid][d]&&tt[cid][d][sid]; if(!a)return;
      a.forEach(e=>{ if(!e.sid)return; const k=e.sid+'|'+(e.grp||'')+'|'+(e.tid||''); map[k]=(map[k]||0)+1; }); }));
    const byST={};
    Object.entries(map).forEach(([k,hours])=>{ const [sid,grp,tid]=k.split('|'); const whole=grp==='';
      const mk=sid+'|'+tid+'|'+hours+'|'+(whole?'W':'G'); const o=byST[mk]||(byST[mk]={sid,tid,hours,grps:[]}); if(!whole)o.grps.push(grp); });
    Object.values(byST).forEach(o=>assignments.push({id:uid(),tid:o.tid||null,sid:o.sid,cid,groups:o.grps,hours:o.hours}));
  });

  return {
    settings:{
      schoolName:'Escola Pré-Universitária Sagrada Família',
      brandTop:'ESCOLA PRÉ-UNIVERSITÁRIA',brandMain:'SAGRADA FAMÍLIA',brandSub:'da Maxixe',
      city:'Maxixe, Moçambique',
      address:'Av. Americo Boavida, Maxixe', cell:'87 123 4466',
      email:'info@esagrada.com', website:'esagrada.com',
      year:'2026', logo:DEFAULT_LOGO, _logoSeed:true,
      director:'Pe. Roberto Giuseppe Maver', directorName:'O Director',
      adjunto:'Milton Tomás Taela Guilima', adjuntoRole:'Director Adjunto Pedagógico',
      hino:{on:true,start:'07:00',end:'07:30',label:'Hino Nacional – Sapiência Matinal'},
      lunch:{start:'12:35',end:'13:30'},
      saida:'15:30',
      groupColors:{A:'#c0356a',B1:'#2155b8',B2:'#0e7d52',B4:'#6d3fb0'},
      expandGroups:false,
    },
    grid:{
      morning:[{id:'m1',s:'07:30',e:'08:15'},{id:'m2',s:'08:20',e:'09:05'},{id:'m3',s:'09:10',e:'09:55'},{id:'m4',s:'10:10',e:'10:55'},{id:'m5',s:'11:00',e:'11:45'},{id:'m6',s:'11:50',e:'12:35'}],
      afternoon:[{id:'a1',s:'13:30',e:'14:25'},{id:'a2',s:'14:35',e:'15:30'}],
    },
    cats, subjects, teachers, classes, assignments, tt,
    rules: seedRules(subjects, S),
    archive: [],
  };
}
function seedRules(subjects, S){
  const subj={};
  subjects.forEach(s=>{ subj[s.id]={double:false,avoidFirst:false,avoidLast:false,maxPerDay:2,period:'any'}; });
  // alguns exemplos sensatos
  if(S['Matemática']) subj[S['Matemática']].double=true;
  if(S['Português'])  subj[S['Português']].double=true;
  if(S['Educação Física']){ subj[S['Educação Física']].avoidFirst=true; }
  if(S['Filosofia']) subj[S['Filosofia']].maxPerDay=1;
  return {
    global:{ keepCats:['ex','ci'], strictFirstLast:false, balanceDays:true, freeText:'' },
    subj,
  };
}

/* ---------- LOOKUPS ---------- */
const getCat = id => DB.cats.find(c=>c.id===id);
const getSubj = id => DB.subjects.find(s=>s.id===id);
const getTeacher = id => DB.teachers.find(t=>t.id===id);
function ensureExtras(){ if(!Array.isArray(DB.extras)) DB.extras=[]; DB.extras.forEach(e=>{ if(!Array.isArray(e.alunos)) e.alunos=[]; if(typeof e.custoMes!=='number') e.custoMes=+e.custoMes||0; if(typeof e.mesInicio!=='number') e.mesInicio=+e.mesInicio||2; if(typeof e.nMeses!=='number') e.nMeses=+e.nMeses||10;
  /* migração: inscrições antigas eram só o código (string); passam a {cod,desde} — "desde" assume o mês de início da atividade (opção mais conservadora) */
  e.alunos = e.alunos.map(a => (typeof a==='string') ? {cod:a, desde:e.mesInicio} : a);
}); return DB.extras; }
const getExtra = id => ensureExtras().find(e=>e.id===id);
function extraDoAluno(cod, exceptId){ return ensureExtras().find(e=> e.id!==exceptId && (e.alunos||[]).some(a=>a.cod===cod)) || null; }
function extraMonths(e){ const a=[]; for(let i=0;i<e.nMeses;i++){ let m=e.mesInicio+i; while(m>12)m-=12; a.push(m);} return a; }
function studentExtra(cod){ for(const e of ensureExtras()){ const enr=(e.alunos||[]).find(a=>a.cod===cod); if(enr) return {e,enr}; } return null; }
const getClass = id => DB.classes.find(c=>c.id===id);
function teacherLabel(t){return ((t.title?t.title+' ':'')+t.name).trim();}
function entryName(e){ if(e.sid){const s=getSubj(e.sid);return s?s.name:'?';} return e.txt||'—'; }
function entryColor(e){
  let cid=e.catId; if(!cid&&e.sid){const s=getSubj(e.sid);cid=s&&s.catId;}
  const c=cid?getCat(cid):null; return c?c.color:'#94a3b8';
}
function slotsFor(cid){ /* returns ordered lessons with period info */ }

/* ---------- TOAST / MODAL ---------- */
let toastT;
function toast(msg,err){
  const t=$('#toast'); t.textContent=msg; t.className='toast on'+(err?' err':'');
  clearTimeout(toastT); toastT=setTimeout(()=>t.className='toast',2200);
}
function openModal(html,wide){
  const m=$('#modal'); m.className='modal'+(wide?' wide':''); m.innerHTML=html;
  $('#mask').classList.add('on');
}
function closeModal(){ $('#mask').classList.remove('on'); }
$('#mask').addEventListener('click',e=>{ if(e.target.id==='mask') closeModal(); });
document.addEventListener('keydown',e=>{ if(e.key==='Escape') closeModal(); });

/* ==================== CUSTOM ELEGANT PICKER MODAL ==================== */
function openPickerModal({ title, subtitle, items, selectedValue, onSelect }) {
  function getListHtml(term) {
    const q = (term || '').toLowerCase().trim();
    const filtered = items.filter(it => 
      it.label.toLowerCase().includes(q) || (it.sublabel && it.sublabel.toLowerCase().includes(q))
    );
    if (!filtered.length) {
      return `<div style="text-align:center;padding:28px 16px;color:var(--text-dim,#888);font-size:13px">Nenhum resultado encontrado.</div>`;
    }
    return filtered.map(it => {
      const isSel = String(it.value) === String(selectedValue);
      const initials = (it.label || '?').split(' ').map(w => w[0]).slice(0, 2).join('').toUpperCase();
      const bg = it.bg || 'linear-gradient(135deg,#3b82f6,#2563eb)';
      return `<div class="picker-item-row" data-val="${esc(it.value)}" style="display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:12px;margin-bottom:8px;cursor:pointer;background:${isSel ? 'var(--surface-2, rgba(59,130,246,0.12))' : 'var(--card-bg, #fff)'};border:1.5px solid ${isSel ? 'var(--brand-blue, #3b82f6)' : 'var(--border-color, #e2e8f0)'};box-shadow:${isSel ? '0 3px 12px rgba(59,130,246,0.2)' : '0 1px 3px rgba(0,0,0,0.03)'};transition:all 0.15s ease">
        <div style="width:42px;height:42px;border-radius:50%;background:${bg};color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:14px;flex-shrink:0;box-shadow:0 2px 8px rgba(0,0,0,0.15)">
          ${it.icon || initials}
        </div>
        <div style="flex:1;min-width:0">
          <div style="font-weight:700;font-size:14px;color:${isSel ? 'var(--brand-blue, #3b82f6)' : 'var(--title-color, #0f172a)'};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(it.label)}</div>
          ${it.sublabel ? `<div style="font-size:12px;color:var(--text-dim, #64748b);margin-top:2px">${esc(it.sublabel)}</div>` : ''}
        </div>
        <div style="width:24px;height:24px;border-radius:50%;border:2px solid ${isSel ? 'var(--brand-blue, #3b82f6)' : 'var(--border-color, #cbd5e1)'};background:${isSel ? 'var(--brand-blue, #3b82f6)' : 'transparent'};display:flex;align-items:center;justify-content:center;color:#fff;font-size:12px;font-weight:800;flex-shrink:0">
          ${isSel ? '✓' : ''}
        </div>
      </div>`;
    }).join('');
  }

  openModal(`
    <div class="modal-h" style="padding:16px 20px;border-bottom:1px solid var(--border-color)">
      <div>
        <h3 style="margin:0;font-size:17px;font-weight:800;color:var(--title-color)">${esc(title || 'Selecionar')}</h3>
        ${subtitle ? `<div style="font-size:12px;color:var(--text-dim);margin-top:2px">${esc(subtitle)}</div>` : ''}
      </div>
      <button class="xbtn" onclick="closeModal()">${I.x}</button>
    </div>
    <div class="modal-b" style="padding:16px;max-height:75vh;overflow-y:auto">
      ${items.length > 5 ? `
        <div style="margin-bottom:12px">
          <input type="text" id="pkSearch" placeholder="🔍 Pesquisar..." style="width:100%;padding:10px 14px;border-radius:10px;border:1px solid var(--border-color);background:var(--surface-2);color:var(--text-main);font-size:13px">
        </div>
      ` : ''}
      <div id="pkContainer">${getListHtml('')}</div>
    </div>
  `);

  function bindItemClicks() {
    document.querySelectorAll('.picker-item-row').forEach(row => {
      row.onclick = () => {
        const val = row.dataset.val;
        closeModal();
        onSelect(val);
      };
    });
  }

  const sInp = $('#pkSearch');
  if (sInp) {
    sInp.oninput = (e) => {
      $('#pkContainer').innerHTML = getListHtml(e.target.value);
      bindItemClicks();
    };
  }
  bindItemClicks();
}

function selectTeacherModal(selectedId, onSelect) {
  const sorted = DB.teachers.slice().sort((a,b) => (a.name||'').localeCompare(b.name||''));
  const items = sorted.map(t => {
    const st = typeof teacherStats === 'function' ? teacherStats(t.id) : null;
    const sub = st ? `${st.total} aula(s) · ${st.classes.join(', ')||"Sem turmas"}` : (t.departamento || 'Docente');
    const bgColors = ['linear-gradient(135deg,#3b82f6,#2563eb)','linear-gradient(135deg,#10b981,#059669)','linear-gradient(135deg,#8b5cf6,#6d28d9)','linear-gradient(135deg,#f59e0b,#d97706)','linear-gradient(135deg,#ec4899,#be185d)'];
    const idx = (t.name.length + (t.id.charCodeAt(0)||0)) % bgColors.length;
    const iconHtml = t.foto ? `<img src="${t.foto}" style="width:100%;height:100%;object-fit:cover;border-radius:50%">` : null;
    return {
      value: t.id,
      label: teacherLabel(t),
      sublabel: sub,
      icon: iconHtml,
      bg: bgColors[idx]
    };
  });
  openPickerModal({
    title: 'Selecione o Professor',
    subtitle: `${DB.teachers.length} docentes cadastrados`,
    items,
    selectedValue: selectedId,
    onSelect
  });
}

function selectClassModal(selectedId, onSelect) {
  let classes = DB.classes;
  const isTeacherRole = (typeof PREVIEW_ROLE !== 'undefined' && (PREVIEW_ROLE === 'professor' || PREVIEW_ROLE === 'diretor')) ||
    (typeof AUTH_USER !== 'undefined' && AUTH_USER && (AUTH_USER.role === 'professor' || AUTH_USER.role === 'diretor'));

  if (isTeacherRole) {
    const tid = typeof currentTeacherId === 'function' ? currentTeacherId() : '';
    if (tid) {
      const myTks = typeof getTeacherTurmaKeys === 'function' ? getTeacherTurmaKeys(tid) : [];
      if (myTks && myTks.length > 0) {
        const filtered = classes.filter(c => {
          const cNameL = String(c.name).toLowerCase();
          const cIdL = String(c.id).toLowerCase();
          return myTks.some(tk => {
            const tkL = String(tk).toLowerCase();
            return tkL === cIdL || tkL === cNameL || cNameL.includes(tkL) || tkL.includes(cNameL);
          });
        });
        if (filtered.length > 0) classes = filtered;
      }
    }
  }

  const items = classes.map(c => {
    const bg = c.type === 'mista' ? 'linear-gradient(135deg,#8b5cf6,#6d28d9)' : 'linear-gradient(135deg,#3b82f6,#2563eb)';
    return {
      value: c.id,
      label: `Turma ${c.name}`,
      sublabel: c.type === 'mista' ? `Mista (${c.groups.join('/')})` : 'Turma inteira',
      bg
    };
  });
  openPickerModal({
    title: 'Selecione a Turma',
    subtitle: `${classes.length} turma(s) disponível(is)`,
    items,
    selectedValue: selectedId,
    onSelect
  });
}

function selectPairModal(selectedPair, onSelect) {
  const tid = typeof currentTeacherId === 'function' ? currentTeacherId() : DB.teachers[0]?.id;
  const pairs = typeof plPairs === 'function' ? plPairs(tid) : [];
  const items = pairs.map(p => {
    const pairKey = p.tk + '::' + p.disc;
    return {
      value: pairKey,
      label: `Turma ${p.tk} · ${p.disc}`,
      sublabel: `Disciplina atribuída a ${teacherLabel(getTeacher(tid))}`,
      icon: '📚',
      bg: 'linear-gradient(135deg,#10b981,#059669)'
    };
  });
  openPickerModal({
    title: 'Selecione a Turma e Disciplina',
    subtitle: `Disciplinas atribuídas a ${teacherLabel(getTeacher(tid))}`,
    items,
    selectedValue: selectedPair,
    onSelect
  });
}



/* ---------- NAV / ROUTER (organização por grupos) ---------- */
