const NAVFLAT = [NAV_TOP, NAV_PORTARIA, NAV_BOTTOM].concat(NAVGROUPS.flatMap(g=>g.items))
  .concat(Object.entries({rules:'Regras de composição',grid:'Vista Turmas',tview:'Vista Professores',export:'Impressões',
    test:'Testes',cadernetas:'Cadernetas',pautas:'Pautas',alunos:'Notas dos Alunos',docs:'Impressões'}).map(([id,label])=>({id,label})));
const NAV = NAVFLAT; /* compat */
const SUBLABEL = {rules:'Regras de composição', grid:'Vista Turmas', tview:'Vista Professores', export:'Impressões',
  test:'Testes', cadernetas:'Cadernetas', pautas:'Pautas', alunos:'Notas dos Alunos', docs:'Impressões'};
const ICONOF = {rules:'magic', grid:'classes', tview:'user', export:'exp', test:'edit', cadernetas:'doc', pautas:'clipboard', alunos:'students', docs:'doc'};
function hubTabs(subIds, activeId){
  const allow=allowedSet(); const relabel=ROLE_RELABEL[PREVIEW_ROLE]||{};
  const avail=subIds.filter(id=>!allow||allow.has(id));
  if(avail.length<=1) return '';
  return `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px">${avail.map(id=>{
    const lbl=relabel[id]||SUBLABEL[id]||id; const on=activeId===id;
    return `<button class="btn ${on?'pri':''}" onclick="go('${id}')">${I[ICONOF[id]]||''} ${esc(lbl)}</button>`;
  }).join('')}</div>`;
}
const HUB_BOX_TINTS=['#e8effb','#f6edd6','#e6f4ec'];
function hubTabsGrouped(groups, activeId, tints){
  const allow=allowedSet(); const relabel=ROLE_RELABEL[PREVIEW_ROLE]||{};
  const pal=tints||HUB_BOX_TINTS;
  const boxes=groups.map(g=>g.filter(id=>!allow||allow.has(id))).filter(g=>g.length);
  const total=boxes.reduce((a,g)=>a+g.length,0);
  if(total<=1) return '';
  return `<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px">${boxes.map((g,i)=>`
    <div style="display:flex;gap:7px;flex-wrap:wrap;background:${pal[i%pal.length]};border-radius:12px;padding:6px">${g.map(id=>{
      const lbl=relabel[id]||SUBLABEL[id]||id; const on=activeId===id;
      return `<button class="btn ${on?'pri':''}" onclick="go('${id}')">${I[ICONOF[id]]||''} ${esc(lbl)}</button>`;
    }).join('')}</div>`).join('')}</div>`;
}
function groupOfView(id){ return NAVGROUPS.find(g=>g.items.some(it=>it.id===id||(it.subs&&it.subs.includes(id)))); }
let NAVOPEN = new Set(); /* todos fechados ao abrir; abrem-se ao navegar */
function toggleGroup(id){ if(NAVOPEN.has(id))NAVOPEN.delete(id); else NAVOPEN.add(id); buildNav(); }
function roleSelectorHtml(){
  const opts = Object.entries(ROLES).map(([k,v])=>`<option value="${k}" ${PREVIEW_ROLE===k?'selected':''}>${v.label}</option>`).join('');
  return `<div style="padding:10px 12px;border-bottom:1px solid rgba(255,255,255,.08)">
    <div style="font-size:9.5px;font-weight:800;letter-spacing:1px;color:rgba(255,255,255,.4);margin-bottom:5px">PRÉ-VISUALIZAR COMO</div>
    <select id="roleSel" style="width:100%;background:rgba(255,255,255,.1);color:#fff;border:1px solid rgba(255,255,255,.18);border-radius:8px;padding:7px 8px;font-size:13px;font-weight:600">${opts}</select>
  </div>`;
}
function navBadge(id){
  if(PREVIEW_ROLE==='professor'){
    if(id==='anag'||id==='alunos'){
      const myTid = currentTeacherId();
      const myTks = getTeacherTurmaKeys(myTid);
      return myTks.reduce((a,k)=>a+Object.keys(NOTAS.turmas[k]?.roster||{}).length,0);
    }
    return '';
  }
  if(PREVIEW_ROLE!=='direcao') return '';
  if(id==='classes')return DB.classes.length;
  if(id==='teachers')return DB.teachers.length;
  if(id==='subjects')return DB.subjects.length;
  if(id==='alunos')return Object.values(NOTAS.turmas).reduce((a,t)=>a+Object.keys(t.roster).length,0);
  if(id==='anag'){ensureAnag();const f=Object.keys(DB.anag).filter(c=>anagFilled(c)>0).length;return f||'';}
  return '';
}
function navItemBtn(n,indent){
  if(n.subs){
    const allow=allowedSet(); const relabel=ROLE_RELABEL[PREVIEW_ROLE]||{};
    const avail=n.subs.filter(s=>!allow||allow.has(s));
    if(!avail.length) return '';
    const isOn=avail.includes(UI.view);
    const goTarget=isOn?UI.view:avail[0];
    const label=avail.length===1?(relabel[avail[0]]||SUBLABEL[avail[0]]||n.label):n.label;
    return `<button data-go="${goTarget}" class="${isOn?'on':''}" ${indent?'style="padding-left:34px"':''}>${I[n.icon]||I.doc}<span>${label}</span></button>`;
  }
  const b=navBadge(n.id);
  return `<button data-go="${n.id}" class="${UI.view===n.id?'on':''}" ${indent?'style="padding-left:34px"':''}>${I[n.icon]||I.doc}<span>${n.label}</span>${b!==''?`<span class="badge">${b}</span>`:''}</button>`;
}
function allowedSet(){ const a=ROLE_NAV[PREVIEW_ROLE]; return a==='*'?null:new Set(a); }
function userCardHtml() {
  if (!AUTH_USER) return '';
  const roleLabel = ROLES[AUTH_USER.role] ? ROLES[AUTH_USER.role].label : AUTH_USER.role;
  return `
    <div style="padding:12px;border-bottom:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.03)">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">
        <div style="width:36px;height:36px;border-radius:10px;background:rgba(255,255,255,.12);display:grid;place-items:center;font-size:18px;border:1px solid rgba(255,255,255,.15)">
          ${AUTH_USER.avatar || '👤'}
        </div>
        <div style="flex:1;min-width:0">
          <div style="font-size:13px;font-weight:700;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">
            ${esc(AUTH_USER.nome)}
          </div>
          <div style="display:inline-block;font-size:10px;font-weight:700;padding:2px 7px;border-radius:999px;background:rgba(255,255,255,.15);color:rgba(255,255,255,.85)">
            ${esc(roleLabel)}
          </div>
        </div>
      </div>
      <div style="display:flex;gap:6px">
        <button type="button" onclick="openChangePassModal()" style="flex:1;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.12);color:#fff;padding:5px 6px;border-radius:6px;font-size:11px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:4px">
          🔑 Password
        </button>
        <button type="button" onclick="doLogout()" style="background:rgba(220,38,38,.2);border:1px solid rgba(220,38,38,.4);color:#fca5a5;padding:5px 8px;border-radius:6px;font-size:11px;font-weight:700;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:4px">
          🚪 Sair
        </button>
      </div>
    </div>
  `;
}
function buildNav(){
  const allow=allowedSet(); const relabel=ROLE_RELABEL[PREVIEW_ROLE]||{};
  let html = userCardHtml();
  if (AUTH_USER && AUTH_USER.role === 'direcao') {
    html += roleSelectorHtml();
  }
  html += navItemBtn(NAV_TOP,false);
  if(!allow || allow.has('portaria')) html += navItemBtn(NAV_PORTARIA,false);
  NAVGROUPS.forEach(g=>{
    let items=g.items.filter(it=> it.subs ? it.subs.some(s=>!allow||allow.has(s)) : (!allow||allow.has(it.id)) );
    if(!items.length) return;
    items=items.map(it=>relabel[it.id]?Object.assign({},it,{label:relabel[it.id]}):it);
    if(g.flat || items.length===1){ html += items.map(it=>navItemBtn(it,false)).join(''); return; }
    const open=NAVOPEN.has(g.id);
    html += `<div class="navgrp"><button class="navgrphd" onclick="toggleGroup('${g.id}')" style="width:100%;display:flex;align-items:center;gap:8px;background:none;border:none;color:rgba(255,255,255,.5);font-size:10.5px;font-weight:800;letter-spacing:1px;text-transform:uppercase;padding:13px 14px 5px;cursor:pointer"><span style="flex:1;text-align:left">${g.label}</span><span style="font-size:10px">${open?'▾':'▸'}</span></button>`;
    if(open) html += items.map(it=>navItemBtn(it,true)).join('');
    html += `</div>`;
  });
  if(!allow || allow.has('config')) html += navItemBtn(NAV_BOTTOM,false);
  $('#nav').innerHTML = html;
  if($('#roleSel')) $('#roleSel').onchange = e=>setRole(e.target.value);
  $('#nav').querySelectorAll('button[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
  let logo = DB.settings && DB.settings.logo ? DB.settings.logo : DEFAULT_LOGO;
  if(logo && logo.startsWith('/assets/')) logo = '.' + logo;
  $('#brandMark').innerHTML = logo ? `<img src="${logo}" style="width:42px;height:42px;border-radius:11px;object-fit:contain">` : I.cap;
  $('#yearPill').textContent = DB.settings.year;
  const banner=$('#previewBanner');
  if(banner){ banner.style.display='none'; }
}
window._portariaLocked = true;
window._portariaUnlockTimer = null;

function applyPortariaLockState() {
  if (typeof UI !== 'undefined' && UI.view === 'portaria' && window._portariaLocked !== false) {
    window._portariaLocked = true;
    document.body.classList.add('portaria-locked');
  } else {
    document.body.classList.remove('portaria-locked');
  }
}

function togglePortariaPassInput(targetView) {
  let pop = document.getElementById('portaria-pass-popover');
  if (pop) {
    closePortariaPassPrompt();
    return;
  }

  pop = document.createElement('div');
  pop.id = 'portaria-pass-popover';
  pop.setAttribute('style', 'position:fixed;top:14px;right:16px;z-index:999999;background:var(--bg-card,#ffffff);border:2px solid var(--brand,#0e7d52);padding:12px 16px;border-radius:16px;box-shadow:0 12px 32px rgba(0,0,0,0.3);display:flex;align-items:center;gap:10px;animation:fadeIn 0.2s ease');

  let count = 5;
  pop.innerHTML = `
    <div style="display:flex;align-items:center;gap:8px">
      <span style="font-size:16px">🔒</span>
      <div style="font-size:12px;font-weight:800;color:var(--txt)">
        Senha (<span id="portaria-timer-num" style="color:#c1121f;font-weight:800">${count}</span>s):
      </div>
    </div>
    <input type="password" id="portaria-pass-input" placeholder="Digite..." autofocus style="width:110px;padding:6px 10px;border-radius:10px;border:1.5px solid var(--line);font-size:13px;outline:none" onkeydown="if(event.key==='Enter')checkPortariaPass('${targetView || ''}')">
    <button class="btn-brand" onclick="checkPortariaPass('${targetView || ''}')" style="padding:6px 12px;border-radius:10px;font-size:12px;font-weight:700">OK</button>
  `;

  document.body.appendChild(pop);

  setTimeout(() => {
    const inp = document.getElementById('portaria-pass-input');
    if (inp) inp.focus();
  }, 50);

  if (window._portariaUnlockTimer) clearInterval(window._portariaUnlockTimer);

  window._portariaUnlockTimer = setInterval(() => {
    count--;
    const numEl = document.getElementById('portaria-timer-num');
    if (numEl) numEl.textContent = count;
    if (count <= 0) {
      closePortariaPassPrompt();
    }
  }, 1000);
}

function closePortariaPassPrompt() {
  if (window._portariaUnlockTimer) {
    clearInterval(window._portariaUnlockTimer);
    window._portariaUnlockTimer = null;
  }
  const pop = document.getElementById('portaria-pass-popover');
  if (pop) pop.remove();
}

function checkPortariaPass(targetView) {
  const inp = document.getElementById('portaria-pass-input');
  if (!inp) return;
  const val = String(inp.value || '').trim();

  const validPasses = ['1234'];
  if (typeof AUTH_USER !== 'undefined' && AUTH_USER && AUTH_USER.pass) {
    validPasses.push(String(AUTH_USER.pass).trim());
  }
  if (typeof DB !== 'undefined' && DB && Array.isArray(DB.users)) {
    DB.users.forEach(u => { if (u.pass) validPasses.push(String(u.pass).trim()); });
  }

  if (validPasses.includes(val)) {
    closePortariaPassPrompt();
    window._portariaLocked = false;
    document.body.classList.remove('portaria-locked');
    if (typeof toast === 'function') toast('🔓 Portaria desbloqueada!');
    if (targetView && targetView !== 'portaria') {
      go(targetView);
    } else if (typeof UI !== 'undefined' && UI.view === 'portaria') {
      render();
    }
  } else {
    if (typeof toast === 'function') toast('❌ Palavra-passe incorreta!');
    inp.value = '';
    inp.focus();
  }
}

const VIEWS={};
function go(v){
  if (typeof UI !== 'undefined' && UI.view === 'portaria' && window._portariaLocked !== false && v !== 'portaria') {
    if (typeof toast === 'function') toast('🔒 Modo Portaria Bloqueado! Insira a palavra-passe para sair.');
    togglePortariaPassInput(v);
    return;
  }
  if (v !== 'portaria') {
    document.body.classList.remove('portaria-locked');
  }
  UI.view=v;
  try {
    const g=groupOfView(v);
    if(g)NAVOPEN.add(g.id);
    buildNav();
    const t=NAVFLAT.find(n=>n.id===v);
    if(t && t.label) {
      const el=$('#topTitle');
      if(el && el.childNodes && el.childNodes[0]) el.childNodes[0].nodeValue=t.label;
    }
  } catch(e) { console.error('go() error:', e); }
  render();
  try { window.scrollTo&&($('#root').scrollTop=0); } catch(e){}
}
function setSub(s){
  const el=$('#topSub');
  if(el) el.textContent=s;
}
function autoGrowTextarea(el) {
  if (!el) return;
  el.style.height = 'auto';
  const minH = parseInt(el.dataset.minH || '42', 10);
  const scrollH = el.scrollHeight;
  el.style.height = Math.max(scrollH + 4, minH) + 'px';
}

function autoGrowAllTextareas() {
  setTimeout(() => {
    document.querySelectorAll('textarea.auto-grow, textarea[oninput*="scrollHeight"], textarea[onchange*="pdFunc"], textarea[onchange*="quinzRowSet"], textarea[onchange*="plUnitSet"]').forEach(ta => {
      autoGrowTextarea(ta);
    });
  }, 40);
}

if (typeof window !== 'undefined') {
  window.addEventListener('resize', autoGrowAllTextareas);
}

function render(){
  const r=$('#root');
  if(!r) return;
  r.innerHTML='';
  try {
    const fn = VIEWS[UI.view] || (()=>r.innerHTML='<div class="empty">Em construção</div>');
    fn(r);
    autoGrowAllTextareas();
  } catch(e) {
    console.error('Render error in view ' + UI.view + ':', e);
    r.innerHTML=`<div class="card" style="padding:24px;margin:20px;background:#fff5f5;border:1.5px solid #f87171;border-radius:16px;color:#991b1b">
      <h3 style="margin-top:0">Erro ao renderizar (${esc(UI.view)})</h3>
      <p style="font-size:13px;font-family:monospace;background:#fee2e2;padding:10px;border-radius:8px">${esc(e.stack || e.toString())}</p>
      <button class="btn sm" onclick="go('dash')">Voltar ao Painel</button>
    </div>`;
  }
}

/* ============================================================
   SHARED HELPERS
   ============================================================ */
const DIA_BY_JS = { 1: 'seg', 2: 'ter', 3: 'qua', 4: 'qui', 5: 'sex', 6: 'sab', 0: 'dom' };
const DIA_FULL = { seg: 'Segunda-feira', ter: 'Terça-feira', qua: 'Quarta-feira', qui: 'Quinta-feira', sex: 'Sexta-feira', sab: 'Sábado', dom: 'Domingo' };
const DAYS_ORDER = ['seg', 'ter', 'qua', 'qui', 'sex', 'sab'];

let PREVIEW_TEACHER = null;
function currentTeacherId(){
  if (AUTH_USER && DB && Array.isArray(DB.teachers)) {
    if (AUTH_USER.role === 'professor' || AUTH_USER.role === 'diretor') {
      const uName = String(AUTH_USER.nome || '').trim().toLowerCase();
      const uId = String(AUTH_USER.id || '').trim().toLowerCase();
      const match = DB.teachers.find(t => {
        if (String(t.id).toLowerCase() === uId) return true;
        const tName = String(t.name || t.nome || '').trim().toLowerCase();
        const tLbl = String(typeof teacherLabel === 'function' ? teacherLabel(t) : '').trim().toLowerCase();
        if (tName === uName || tLbl === uName) return true;
        if (uName.includes('roberto') && (tName.includes('roberto') || tLbl.includes('roberto'))) return true;
        if (uName.includes('maver') && (tName.includes('maver') || tLbl.includes('maver'))) return true;
        return false;
      });
      if (match) return match.id;
    }
  }
  if(PREVIEW_TEACHER && DB && DB.teachers && DB.teachers.some(t=>t.id===PREVIEW_TEACHER)) return PREVIEW_TEACHER;
  return (DB && DB.teachers && DB.teachers[0]) ? DB.teachers[0].id : '';
}

function getTeacherTurmaKeys(tid){
  if(!tid) return [];
  const allTks = typeof turmaKeys === 'function' ? turmaKeys() : Object.keys((typeof NOTAS !== 'undefined' && NOTAS.turmas) ? NOTAS.turmas : {});
  const matched = new Set();

  const tObj = typeof getTeacher === 'function' ? getTeacher(tid) : null;
  const tName = tObj ? (tObj.name || tObj.nome || '').trim().toLowerCase() : '';
  const tLabel = tObj && typeof teacherLabel === 'function' ? teacherLabel(tObj).trim().toLowerCase() : '';

  // 1. Check DT (Director de Turma)
  const dts = (DB && DB.diretoresTurma) || {};
  Object.entries(dts).forEach(([tk, val]) => {
    const valL = String(val||'').trim().toLowerCase();
    if (valL && (valL === String(tid).toLowerCase() || valL === tName || valL === tLabel)) {
      matched.add(tk);
    }
  });

  // 2. Check TURMA_PROFS
  if (typeof TURMA_PROFS !== 'undefined') {
    Object.entries(TURMA_PROFS).forEach(([tk, discs]) => {
      Object.values(discs).forEach(pName => {
        const pL = String(pName||'').trim().toLowerCase();
        if (pL && (pL === tName || pL === tLabel || (tName && pL.includes(tName)) || (tLabel && pL.includes(tLabel)))) {
          matched.add(tk);
        }
      });
    });
  }

  // 3. Check NOTAS.profs
  if (typeof NOTAS !== 'undefined' && NOTAS.profs) {
    Object.entries(NOTAS.profs).forEach(([disc, pName]) => {
      const pL = String(pName||'').trim().toLowerCase();
      if (pL && (pL === tName || pL === tLabel || (tName && (pL.includes(tName) || tName.includes(pL))) || (tLabel && (pL.includes(tLabel) || tLabel.includes(pL))))) {
        allTks.forEach(tk => {
          if (NOTAS.turmas[tk] && NOTAS.turmas[tk].discs && NOTAS.turmas[tk].discs.includes(disc)) {
            matched.add(tk);
          }
        });
      }
    });
  }

  // 4. Check DB.assignments & schedule
  const st = typeof teacherStats === 'function' ? teacherStats(tid) : null;
  const clsNames = (st && Array.isArray(st.classes)) ? [...st.classes] : [];
  const asgs = (DB && Array.isArray(DB.assignments)) ? DB.assignments.filter(a => a.tid === tid) : [];
  const asgCids = asgs.map(a => a.cid);

  if (typeof teacherSchedule === 'function') {
    const sched = teacherSchedule(tid);
    (typeof DAYS !== 'undefined' ? DAYS : []).forEach(d => {
      const day = sched[d] || {};
      Object.values(day).forEach(list => {
        (list || []).forEach(x => {
          if (x && x.cls) clsNames.push(x.cls);
        });
      });
    });
  }

  allTks.forEach(tk => {
    const t = NOTAS && NOTAS.turmas ? NOTAS.turmas[tk] : null;
    if (!t) return;
    const nameWithT = `${t.classe} T${t.turma}`.toLowerCase();
    const nameClasseOnly = String(t.classe).toLowerCase();
    const tkLower = String(tk).toLowerCase();

    const matchName = clsNames.some(cn => {
      const cnl = String(cn).toLowerCase();
      return cnl === nameWithT || cnl === tkLower || cnl === nameClasseOnly;
    });

    const matchAsg = asgCids.some(cid => {
      const cidL = String(cid).toLowerCase();
      if (cidL === tkLower) return true;
      const c = (DB && DB.classes) ? DB.classes.find(x => x.id === cid) : null;
      if (c) {
        const cNameL = String(c.name).toLowerCase();
        return cNameL === nameWithT || cNameL === tkLower;
      }
      return false;
    });

    if (matchName || matchAsg) {
      matched.add(tk);
    }
  });

  return [...matched].sort((a,b) => String(a).localeCompare(String(b), undefined, {numeric: true}));
}

function userTurmaKeys(){
  const all = turmaKeys();
  if (typeof PREVIEW_ROLE !== 'undefined' && PREVIEW_ROLE === 'professor') {
    const tid = currentTeacherId();
    if (tid) {
      const myTks = getTeacherTurmaKeys(tid);
      if (myTks && myTks.length > 0) return myTks;
    }
  }
  return all;
}

function getTeacherDiscsForTurma(tid, tk){
  if (!tk) return [];
  const t = (NOTAS && NOTAS.turmas) ? NOTAS.turmas[tk] : null;
  if (!t) return [];

  if (typeof PREVIEW_ROLE !== 'undefined' && PREVIEW_ROLE !== 'professor' && PREVIEW_ROLE !== 'diretor') {
    return t.discs || [];
  }

  const dts = (DB && DB.diretoresTurma) || {};
  const tObj = typeof getTeacher === 'function' ? getTeacher(tid) : null;
  const tName = tObj ? (tObj.name || tObj.nome || '').trim().toLowerCase() : '';
  const tLabel = tObj && typeof teacherLabel === 'function' ? teacherLabel(tObj).trim().toLowerCase() : '';
  const dtVal = String(dts[tk]||'').trim().toLowerCase();
  const isDt = PREVIEW_ROLE === 'diretor' || (dtVal && (dtVal === String(tid).toLowerCase() || dtVal === tName || dtVal === tLabel));
  if (isDt) {
    return t.discs || [];
  }

  const discs = new Set();

  if (typeof TURMA_PROFS !== 'undefined' && TURMA_PROFS[tk]) {
    Object.entries(TURMA_PROFS[tk]).forEach(([disc, pName]) => {
      const pL = String(pName||'').trim().toLowerCase();
      if (pL && (pL === tName || pL === tLabel || (tName && pL.includes(tName)) || (tLabel && pL.includes(tLabel)))) {
        discs.add(disc);
      }
    });
  }

  if (typeof NOTAS !== 'undefined' && NOTAS.profs) {
    Object.entries(NOTAS.profs).forEach(([disc, pName]) => {
      const pL = String(pName||'').trim().toLowerCase();
      if (pL && (pL === tName || pL === tLabel || (tName && (pL.includes(tName) || tName.includes(pL))) || (tLabel && (pL.includes(tLabel) || tLabel.includes(pL))))) {
        if (t.discs && t.discs.includes(disc)) {
          discs.add(disc);
        }
      }
    });
  }

  const asgs = (DB && Array.isArray(DB.assignments)) ? DB.assignments.filter(a => a.tid === tid) : [];
  asgs.forEach(a => {
    const c = (DB && DB.classes) ? DB.classes.find(x => x.id === a.cid) : null;
    const matchClass = a.cid === tk || (c && (c.name === tk || `${t.classe} T${t.turma}`.toLowerCase() === String(c.name).toLowerCase()));
    if (matchClass && a.sid) {
      const sj = typeof getSubj === 'function' ? getSubj(a.sid) : null;
      if (sj && sj.name && t.discs.includes(sj.name)) discs.add(sj.name);
    }
  });

  const clsObj = (DB && DB.classes) ? DB.classes.find(c => c.name === tk || c.id === tk || `${t.classe} T${t.turma}`.toLowerCase() === String(c.name).toLowerCase()) : null;
  if (clsObj && DB.tt && DB.tt[clsObj.id]) {
    (typeof DAYS !== 'undefined' ? DAYS : []).forEach(d => {
      const dayGrid = DB.tt[clsObj.id][d] || {};
      Object.values(dayGrid).forEach(arr => {
        (arr || []).forEach(e => {
          if (e.tid === tid && e.sid) {
            const sj = typeof getSubj === 'function' ? getSubj(e.sid) : null;
            if (sj && sj.name && t.discs.includes(sj.name)) discs.add(sj.name);
          }
        });
      });
    });
  }

  return discs.size > 0 ? (t.discs || []).filter(d => discs.has(d)) : (t.discs || []);
}

function diIsoToday(){ return new Date().toISOString().slice(0,10); }
function diIsoToDia(iso){ if(!iso)return null; const d=new Date(iso+'T12:00:00'); return DIA_BY_JS[d.getDay()]||null; }
function diDiaFromIso(iso){ return diIsoToDia(iso); }
function diFmtData(iso){ if(!iso)return''; const[y,m,dd]=iso.split('-'); return `${dd}/${m}/${y}`; }

function upd(fn,rerender){ if(fn)fn(); persist(); if(rerender)render(); buildNav(); }
function periodRows(slots){
  const rows=[];
  slots.forEach((sl,i)=>{ rows.push({t:'slot',slot:sl});
    if(i<slots.length-1){ const g=gapMin(sl.e,slots[i+1].s); if(g>0) rows.push({t:'break',min:g}); }});
  return rows;
}
function allSlots(){ return [...DB.grid.morning,...DB.grid.afternoon]; }
let _confirmOnYes = null;
function confirmDel(msg,onYes){
  _confirmOnYes = onYes;
  openModal(`<div class="modal-h"><h3>Confirmar</h3><button class="xbtn" onclick="closeModal()">${I.x}</button></div>
  <div class="modal-b"><p style="font-size:14px;line-height:1.6">${esc(msg)}</p></div>
  <div class="modal-f"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn dng" onclick="if(_confirmOnYes){const fn=_confirmOnYes;_confirmOnYes=null;fn();}closeModal();">${I.trash} Eliminar</button></div>`);
}
function field(label,inner,hint){return `<div class="field"><label>${label}${hint?` <span class="hint">${hint}</span>`:''}</label>${inner}</div>`;}

