VIEWS.estrutura=function(r){
  setSub('Tempos lectivos · hino · cores');
  const s=DB.settings;
  r.innerHTML=`
  <div class="vhead"><h1>Estrutura dos tempos</h1><p>Tempos lectivos, intervalos, hino e cores dos grupos. Define a estrutura do dia escolar usada nos horários.</p></div>
  <div class="stack">
    <div class="card"><div class="card-h"><h3>Hino, almoço e saída</h3></div><div class="card-p">
      <label class="checkline"><input type="checkbox" id="cf_hino" ${s.hino.on?'checked':''}> Mostrar barra do Hino / Sapiência Matinal</label>
      <div class="inline" style="margin-top:8px">
        ${field('Texto do hino',`<input type="text" id="cf_hlabel" value="${esc(s.hino.label)}">`)}
        ${field('Início',`<input type="time" id="cf_hs" value="${s.hino.start}">`)}
        ${field('Fim',`<input type="time" id="cf_he" value="${s.hino.end}">`)}
      </div>
      <div class="inline">
        ${field('Almoço — início',`<input type="time" id="cf_ls" value="${s.lunch.start}">`)}
        ${field('Almoço — fim',`<input type="time" id="cf_le" value="${s.lunch.end}">`)}
        ${field('Hora de saída',`<input type="time" id="cf_saida" value="${s.saida}">`)}
      </div>
    </div></div>

    <div class="card"><div class="card-h"><h3>Estrutura dos tempos lectivos</h3><button class="btn sm" id="addSlotM">${I.plus} Tempo manhã</button></div>
      <div class="card-p" id="gridSlots"></div>
    </div>

    <div class="card"><div class="card-h"><h3>Cores dos grupos & opções</h3></div><div class="card-p">
      <div style="display:flex;gap:18px;flex-wrap:wrap;margin-bottom:14px">
        ${Object.entries(s.groupColors).map(([g,col])=>`<label style="display:flex;flex-direction:column;gap:5px;align-items:center;font-size:12px;font-weight:600"><span>${g}</span><input type="color" value="${col}" data-gc="${g}" style="width:46px;height:34px;border:1px solid var(--line);border-radius:8px;padding:2px"></label>`).join('')}
      </div>
      <label class="checkline"><input type="checkbox" id="cf_expand" ${s.expandGroups?'checked':''}> Na vista do professor, repetir disciplinas comuns por cada grupo (ex: <i>Filosofia 10-1/A</i>, <i>/B1</i>, <i>/B2</i>)</label>
      <label class="checkline"><input type="checkbox" id="cf_autocomb" ${s.autoCombine!==false?'checked':''}> Reconhecer <b>aulas combinadas</b> automaticamente (mesmo professor e disciplina à mesma hora não contam como conflito)</label>
    </div></div>
  </div>`;
  renderGridSlots();
  const b=(id,fn)=>{const el=$('#'+id);if(el)el.onchange=()=>{fn(el);persist();buildNav();};};
  b('cf_hlabel',e=>s.hino.label=e.value); b('cf_hs',e=>s.hino.start=e.value); b('cf_he',e=>s.hino.end=e.value);
  b('cf_ls',e=>s.lunch.start=e.value); b('cf_le',e=>s.lunch.end=e.value); b('cf_saida',e=>s.saida=e.value);
  $('#cf_hino').onchange=e=>{s.hino.on=e.target.checked;persist();};
  $('#cf_expand').onchange=e=>{s.expandGroups=e.target.checked;persist();};
  $('#cf_autocomb').onchange=e=>{s.autoCombine=e.target.checked;persist();};
  r.querySelectorAll('[data-gc]').forEach(i=>i.onchange=()=>{s.groupColors[i.dataset.gc]=i.value;persist();});
  $('#addSlotM').onclick=()=>addSlot('morning');
};
function renderGridSlots(){
  const wrap=$('#gridSlots'); if(!wrap)return;
  const row=(p,sl,i,arr)=>`<div class="row" style="padding:8px 0;border-color:var(--line-2)">
    <span class="chip" style="font-family:var(--mono)">${i+1}</span>
    <input type="time" value="${sl.s}" style="width:120px" onchange="editSlot('${p}','${sl.id}','s',this.value)">
    <span style="color:var(--ink-faint)">→</span>
    <input type="time" value="${sl.e}" style="width:120px" onchange="editSlot('${p}','${sl.id}','e',this.value)">
    ${i<arr.length-1?`<span class="meta">intervalo ${gapMin(sl.e,arr[i+1].s)} min</span>`:''}
    <div class="sp"><button class="btn icon ghost dng" onclick="delSlot('${p}','${sl.id}')">${I.trash}</button></div></div>`;
  wrap.innerHTML=`
    <div class="sect-bar" style="border-radius:8px;margin-bottom:6px">Período da manhã</div>
    <div class="list">${DB.grid.morning.map((sl,i)=>row('morning',sl,i,DB.grid.morning)).join('')}</div>
    <div style="height:14px"></div>
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px"><div class="sect-bar" style="border-radius:8px;flex:1">Período da tarde</div><button class="btn sm" style="margin-left:10px" onclick="addSlot('afternoon')">${I.plus} Tempo tarde</button></div>
    <div class="list">${DB.grid.afternoon.map((sl,i)=>row('afternoon',sl,i,DB.grid.afternoon)).join('')}</div>`;
}
function editSlot(p,id,k,v){const sl=DB.grid[p].find(x=>x.id===id);if(sl){sl[k]=v;persist();renderGridSlots();}}
function addSlot(p){const arr=DB.grid[p];const last=arr[arr.length-1];const s=last?last.e:'07:30';arr.push({id:uid(),s,e:s});persist();renderGridSlots();}
function delSlot(p,id){DB.grid[p]=DB.grid[p].filter(x=>x.id!==id);DB.classes.forEach(c=>DAYS.forEach(d=>{if(DB.tt[c.id]&&DB.tt[c.id][d])delete DB.tt[c.id][d][id];}));persist();renderGridSlots();}

