VIEWS.classes=function(r){
  setSub(DB.classes.length+' turma(s)');
  r.innerHTML=`<div class="vhead" style="display:flex;justify-content:space-between;align-items:flex-end">
    <div><h1>Turmas</h1><p>Cada turma pode ser <b>pura</b> (uma só vertente) ou <b>mista</b>, dividida em grupos (A, B1, B2…). Atribuição de Directores de Turma gerida pela Direção.</p></div>
    <button class="btn pri" id="addC">${I.plus} Nova turma</button></div>
    <div class="card"><div class="list">${
      DB.classes.map(c=>{
        const dtName = lpDtName(c.name);
        const dtBadge = dtName ? `<span style="font-size:11px;font-weight:700;background:var(--emerald-light);color:var(--emerald);padding:3px 8px;border-radius:6px;margin-left:8px">👔 DT: ${esc(dtName)}</span>` : `<span style="font-size:11px;font-weight:700;background:var(--amber-light);color:var(--amber);padding:3px 8px;border-radius:6px;margin-left:8px">🟡 Sem DT</span>`;
        return `<div class="row"><span class="chip" style="font-size:14px">${esc(c.name)}</span>
        <div><div class="nm" style="display:flex;align-items:center">${c.type==='mista'?'Turma mista':'Turma pura'}${dtBadge}</div><div class="meta">${c.type==='mista'?'Grupos: '+(c.groups.join(' · ')||'—'):'Sem divisão por grupos'}</div></div>
        <div class="sp"><button class="btn sm" onclick="UI.cls='${c.id}';go('grid')">${I.grid} Horário</button><button class="btn icon ghost" onclick="editClass('${c.id}')">${I.edit}</button><button class="btn icon ghost dng" onclick="delClass('${c.id}')">${I.trash}</button></div></div>`;
      }).join('')||`<div class="empty">${I.classes}<div>Sem turmas. Crie a primeira.</div></div>`
    }</div></div>`;
  $('#addC').onclick=()=>editClass(null);
};
function editClass(id){
  const c=id?getClass(id):{name:'',type:'mista',groups:['A','B1','B2']};
  const curDt = ((DB.diretoresTurma||{})[c.name])||'';
  const assignedT = DB.teachers.find(t => t.id === curDt || teacherLabel(t) === curDt);
  const dtVal = assignedT ? assignedT.id : (curDt || '');

  openModal(`<div class="modal-h"><h3>${id?'Editar':'Nova'} turma</h3><button class="xbtn" onclick="closeModal()">${I.x}</button></div>
  <div class="modal-b">
    ${field('Nome da turma','<input type="text" id="m_name" placeholder="ex: 10-1" value="'+esc(c.name)+'">')}
    ${field('Director de Turma (DT)','<select id="m_dt"><option value="">— Sem Director Atribuído —</option>'+DB.teachers.slice().sort((a,b)=>(a.name||'').localeCompare(b.name||'')).map(t=>`<option value="${t.id}" ${dtVal===t.id?'selected':''}>${esc(teacherLabel(t))}</option>`).join('')+(!assignedT && curDt ? `<option value="${esc(curDt)}" selected>${esc(curDt)}</option>`:'')+'</select>','Atribuído pelo Director ou Director Adjunto')}
    ${field('Tipo','<div class="opt-grid"><button class="opt" data-t="pura">Pura</button><button class="opt" data-t="mista">Mista (com grupos)</button></div>')}
    <div id="grpBox">${field('Grupos','<input type="text" id="m_groups" placeholder="A, B1, B2" value="'+esc(c.groups.join(', '))+'">','separados por vírgula')}</div>
  </div>
  <div class="modal-f"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn pri" id="m_save">Guardar</button></div>`);
  let type=c.type;
  function paint(){ $('#modal').querySelectorAll('[data-t]').forEach(b=>b.classList.toggle('sel',b.dataset.t===type)); $('#grpBox').style.display=type==='mista'?'':'none'; }
  $('#modal').querySelectorAll('[data-t]').forEach(b=>b.onclick=()=>{type=b.dataset.t;paint();}); paint();
  $('#m_save').onclick=()=>{
    const name=$('#m_name').value.trim(); if(!name)return toast('Indique o nome',1);
    const groups=type==='mista'?$('#m_groups').value.split(',').map(x=>x.trim()).filter(Boolean):[];
    const dtSel = $('#m_dt').value;
    if(id){c.name=name;c.type=type;c.groups=groups;}
    else{const nc={id:uid(),name,type,groups};DB.classes.push(nc);DB.tt[nc.id]={};DAYS.forEach(d=>DB.tt[nc.id][d]={});}
    lpSetDt(name, dtSel);
    upd(null,true);closeModal();toast('Turma guardada');
  };
}
function delClass(id){const c=getClass(id);confirmDel(`Eliminar a turma "${c.name}" e o seu horário?`,()=>{DB.classes=DB.classes.filter(x=>x.id!==id);delete DB.tt[id];DB.assignments=DB.assignments.filter(a=>a.cid!==id);upd(null,true);toast('Turma eliminada');});}

/* ============================================================
   DISCIPLINAS
   ============================================================ */
/* ===================== EXTRACURRICULARES ===================== */
let EXUI = { sel:[], desde:{}, q:'', turma:'all', id:null };

function extraActivityStats(e){
  const todayMonth=new Date().getMonth()+1;
  let emDia=0, parcial=0, atraso=0, naoAplica=0, totalRecebido=0;
  (e.alunos||[]).forEach(enr=>{
    const s=finSit(enr.cod);
    const items=s.extraItems.filter(x=>x.extraId===e.id);
    totalRecebido += items.reduce((a,it)=>a+(it.pago||0),0);
    const cur=items.find(x=>x.mes===todayMonth);
    if(!cur){ naoAplica++; return; }
    if(cur.estado==='Pago') emDia++; else if(cur.estado==='Parcial') parcial++; else atraso++;
  });
  return {total:(e.alunos||[]).length, emDia, parcial, atraso, naoAplica, totalRecebido};
}
function extraActivityPayments(id){
  const e=getExtra(id); if(!e) return;
  const todayMonth=new Date().getMonth()+1;
  const rows=(e.alunos||[]).map(enr=>{
    const al=findAluno(enr.cod); if(!al) return '';
    const s=finSit(enr.cod);
    const items=s.extraItems.filter(x=>x.extraId===e.id);
    const cur=items.find(x=>x.mes===todayMonth);
    const chip = !cur ? `<span style="color:#999;font-size:11px">— ainda não aplicável</span>` : estadoChip(cur.estado);
    return `<tr><td style="padding:7px 10px;border-bottom:1px solid #eee">${esc(al.a.nome)}</td>
      <td style="padding:7px 10px;border-bottom:1px solid #eee;font-size:12px;color:#777">${al.t.classe} T${al.t.turma}</td>
      <td style="padding:7px 10px;border-bottom:1px solid #eee;text-align:center">${chip}</td>
      <td style="padding:7px 10px;border-bottom:1px solid #eee;text-align:right;font-size:12px">${fmtMT(items.reduce((a,it)=>a+(it.pago||0),0))}</td>
      <td style="padding:7px 8px;border-bottom:1px solid #eee;text-align:center"><button class="btn" style="padding:3px 9px;font-size:11px" onclick="openAlunoFicha('${enr.cod}','fin')">${I.exp} Abrir ficha</button></td></tr>`;
  }).join('') || `<tr><td colspan="5" style="padding:16px;text-align:center;color:#999">Sem alunos inscritos.</td></tr>`;
  openModal(`<div class="modal-h"><h3>Pagamentos · ${esc(e.nome)}</h3><button class="xbtn" onclick="closeModal()">${I.x}</button></div>
  <div class="modal-b">
    <table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:#eef1f6;color:#26324a;font-size:11px"><th style="padding:6px 10px;text-align:left">Aluno</th><th style="padding:6px 10px;text-align:left">Turma</th><th style="padding:6px 10px">Este mês</th><th style="padding:6px 10px;text-align:right">Recebido (ano)</th><th style="padding:6px 8px">Ficha</th></tr></thead><tbody>${rows}</tbody></table>
  </div>
  <div class="modal-f"><button class="btn" onclick="closeModal()">Fechar</button></div>`, true);
}
function findDuplicateEnrollments(){
  const map={};
  ensureExtras().forEach(e=>{ (e.alunos||[]).forEach(a=>{ (map[a.cod]=map[a.cod]||[]).push(e); }); });
  return Object.entries(map).filter(([cod,list])=>list.length>1).map(([cod,list])=>({cod,activities:list}));
}
VIEWS.extras = function(r){
  ensureExtras(); setSub(DB.extras.length+' atividade(s) extracurricular(es)');
  const dups=findDuplicateEnrollments();
  const dupBanner=dups.length?`<div class="card" style="padding:14px 18px;margin-bottom:16px;border:1.5px solid #f0c4c1;background:#fdf3f2">
    <div style="display:flex;align-items:center;gap:8px;font-weight:700;color:#b3261e;margin-bottom:6px">${I.warn} ${dups.length} aluno(s) inscrito(s) em mais de uma atividade</div>
    <div style="font-size:12.5px;color:#7a3a36">Cada aluno só deve estar inscrito numa atividade. Isto é uma inconsistência nos dados (provavelmente anterior à regra de exclusividade) — não foi corrigida automaticamente para não apagar nada sem confirmação. Abra «Alunos» em cada atividade abaixo e remova a inscrição que não deve manter-se:</div>
    <ul style="margin:8px 0 0 18px;font-size:12.5px;color:#7a3a36;line-height:1.6">
      ${dups.map(d=>{ const al=findAluno(d.cod); return `<li><b>${al?esc(al.a.nome):d.cod}</b> — inscrito em: ${d.activities.map(a=>esc(a.nome)).join(' + ')}</li>`; }).join('')}
    </ul>
  </div>`:'';
  const cards = DB.extras.slice().sort((a,b)=>(a.nome||'').localeCompare(b.nome||'')).map(e=>{
    const prof=getTeacher(e.profId); const nA=(e.alunos||[]).length;
    const mIni=MESES_PT[(e.mesInicio||2)-1]||'—';
    const st=nA?extraActivityStats(e):null;
    return `<div class="card" style="padding:16px 18px;margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap">
        <div style="min-width:0">
          <div style="font-family:var(--serif);font-size:18px;font-weight:700;color:var(--navy)">${esc(e.nome||'—')}</div>
          <div style="font-size:13px;color:#777;margin-top:3px">Professor: <b>${prof?esc(teacherLabel(prof)):'<span style=\'color:#c2342f\'>por atribuir</span>'}</b></div>
          <div style="display:flex;gap:14px;flex-wrap:wrap;margin-top:8px;font-size:12.5px;color:#555">
            <span>Custo mensal: <b>${fmtMT(e.custoMes||0)}</b></span>
            <span>Início: <b>${mIni}</b></span>
            <span>Duração: <b>${e.nMeses||0} ${(e.nMeses===1)?'mês':'meses'}</b></span>
            <span>Inscritos: <b>${nA}</b></span>
          </div>
          ${e.obs?`<div style="font-size:12px;color:#888;margin-top:6px">${esc(e.obs)}</div>`:''}
          ${st?`<div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:9px;font-size:12px;background:#f7f9fc;border:1px solid var(--line);border-radius:8px;padding:7px 11px">
            <span>Este mês: <b style="color:#0e7d52">${st.emDia} em dia</b>${st.parcial?` · <b style="color:#b35309">${st.parcial} parcial</b>`:''}${st.atraso?` · <b style="color:#c2342f">${st.atraso} em atraso</b>`:''}${st.naoAplica?` · <span style="color:#999">${st.naoAplica} ainda não aplicável</span>`:''}</span>
            <span style="margin-left:auto">Recebido (ano): <b>${fmtMT(st.totalRecebido)}</b></span>
          </div>`:''}
        </div>
        <div class="btnrow" style="flex-shrink:0">
          ${nA?`<button class="btn" onclick="extraActivityPayments('${e.id}')" title="Ver situação de pagamento de cada aluno">${I.exp} Pagamentos</button>`:''}
          <button class="btn" onclick="manageExtraAlunos('${e.id}')">${I.students} Alunos (${nA})</button>
          <button class="btn icon ghost" onclick="editExtra('${e.id}')" title="Editar">${I.edit}</button>
          <button class="btn icon ghost dng" onclick="delExtra('${e.id}')" title="Eliminar">${I.trash}</button>
        </div>
      </div></div>`;
  }).join('') || `<div class="empty">${I.cap}<div>Ainda não há atividades extracurriculares. Clique em «Nova atividade» para começar.</div></div>`;

  r.innerHTML = `<div class="vhead" style="display:flex;justify-content:space-between;align-items:flex-end">
      <div><h1>Extracurriculares</h1><p>Atividades extracurriculares com professor próprio e alunos de turmas diferentes. Cada atividade tem um custo mensal que é cobrado na ficha financeira do aluno.</p></div>
      <button class="btn pri" id="addEx">${I.plus} Nova atividade</button></div>
    ${dupBanner}${cards}`;
  $('#addEx').onclick=()=>editExtra(null);
};

function editExtra(id){
  ensureExtras();
  const isNew=!id;
  const e = isNew ? {id:'',nome:'',profId:'',custoMes:0,mesInicio:2,nMeses:10,obs:'',alunos:[]} : Object.assign({},getExtra(id));
  if(!e){toast('Atividade não encontrada',true);return;}
  const profOpts = `<option value="">— por atribuir —</option>` + DB.teachers.slice().sort((a,b)=>(a.name||'').localeCompare(b.name||'')).map(t=>`<option value="${t.id}" ${e.profId===t.id?'selected':''}>${esc(teacherLabel(t))}</option>`).join('');
  const mesOpts = MESES_PT.map((m,i)=>`<option value="${i+1}" ${e.mesInicio===i+1?'selected':''}>${m}</option>`).join('');
  openModal(`<div class="modal-h"><h3>${isNew?'Nova atividade':'Editar atividade'}</h3><button class="xbtn" onclick="closeModal()">${I.x}</button></div>
  <div class="modal-b">
    ${field('Nome da atividade',`<input id="ex_nome" value="${esc(e.nome)}" placeholder="ex.: Coro, Música, Desporto, Inglês reforço">`)}
    ${field('Professor responsável',`<select id="ex_prof">${profOpts}</select>`)}
    <div class="inline">
      ${field('Custo mensal (MT)',`<input id="ex_custo" type="number" min="0" value="${e.custoMes||0}">`)}
      ${field('Mês de início',`<select id="ex_ini">${mesOpts}</select>`)}
      ${field('Nº de meses',`<input id="ex_n" type="number" min="1" max="12" value="${e.nMeses||10}">`)}
    </div>
    ${field('Observações',`<textarea id="ex_obs" rows="2">${esc(e.obs||'')}</textarea>`)}
  </div>
  <div class="modal-f">
    ${!isNew?`<button class="btn" style="color:#b3261e" onclick="closeModal();delExtra('${e.id}')">${I.trash} Eliminar</button>`:''}
    <button class="btn" onclick="closeModal()">Cancelar</button>
    <button class="btn pri" id="ex_save">Guardar</button>
  </div>`);
  $('#ex_save').onclick=()=>{
    const nome=$('#ex_nome').value.trim(); if(!nome){toast('Indique o nome da atividade',true);return;}
    const rec={ id:e.id||uid(), nome, profId:$('#ex_prof').value,
      custoMes:Math.max(0,+$('#ex_custo').value||0), mesInicio:+$('#ex_ini').value||2,
      nMeses:Math.min(12,Math.max(1,+$('#ex_n').value||10)), obs:$('#ex_obs').value.trim(),
      alunos: e.alunos||[] };
    ensureExtras();
    const idx=DB.extras.findIndex(x=>x.id===rec.id);
    if(idx>=0) DB.extras[idx]=rec; else DB.extras.push(rec);
    upd(null,false); closeModal(); toast(isNew?'Atividade criada ✓':'Atividade guardada ✓'); render();
  };
}

function delExtra(id){
  const e=getExtra(id); if(!e) return;
  const nA=(e.alunos||[]).length;
  openModal(`<div class="modal-h"><h3>Eliminar atividade</h3><button class="xbtn" onclick="closeModal()">${I.x}</button></div>
  <div class="modal-b"><p>Tem a certeza que deseja eliminar <b>${esc(e.nome)}</b>?${nA?` Tem <b>${nA}</b> aluno(s) inscrito(s).`:''}</p>
  <p style="font-size:12.5px;color:#888">Esta ação não remove os pagamentos já registados, mas a atividade deixará de aparecer nas fichas.</p></div>
  <div class="modal-f"><button class="btn" onclick="closeModal()">Cancelar</button>
  <button class="btn pri" style="background:#b3261e" onclick="confirmDelExtra('${id}')">Eliminar</button></div>`);
}
function confirmDelExtra(id){ ensureExtras(); DB.extras=DB.extras.filter(e=>e.id!==id); upd(null,false); closeModal(); toast('Atividade eliminada'); render(); }

function clampToExtraMonth(e,m){ const ms=extraMonths(e); return ms.includes(m)?m:ms[0]; }
function manageExtraAlunos(id){
  ensureExtras();
  const e=getExtra(id); if(!e){toast('Atividade não encontrada',true);return;}
  EXUI={ id, sel:(e.alunos||[]).map(a=>a.cod), desde:Object.fromEntries((e.alunos||[]).map(a=>[a.cod,a.desde||e.mesInicio])), q:'', turma:'all' };
  renderExtraAlunosModal();
}
function exToggleAluno(cod){ const i=EXUI.sel.indexOf(cod);
  if(i<0){ const t=extraDoAluno(cod, EXUI.id); if(t){ toast('Aluno já inscrito em: '+t.nome, true); return; }
    EXUI.sel.push(cod); const e=getExtra(EXUI.id); EXUI.desde[cod]=clampToExtraMonth(e,new Date().getMonth()+1); }
  else EXUI.sel.splice(i,1);
  renderExtraAlunosModal(true); }
function exSetDesde(cod,m){ EXUI.desde[cod]=+m; }
function renderExtraAlunosModal(keepFocus){
  const e=getExtra(EXUI.id); if(!e) return;
  const q=EXUI.q.trim().toLowerCase();
  const mesesOpts=extraMonths(e).map(m=>`<option value="${m}">${MESES_PT[m-1]}</option>`).join('');
  let list=allAlunosFin().filter(a=>EXUI.turma==='all'||a.tk===EXUI.turma)
    .filter(a=>!q||a.nome.toLowerCase().includes(q)||a.cod.toLowerCase().includes(q))
    .sort((a,b)=> a.tk===b.tk ? a.num-b.num : a.tk.localeCompare(b.tk));
  const chip=(val,label)=>{ const on=EXUI.turma===val; return `<button onclick="EXUI.turma='${val}';renderExtraAlunosModal()" style="border:1px solid ${on?'#26324a':'var(--line)'};background:${on?'#26324a':'#fff'};color:${on?'#fff':'#26324a'};border-radius:9px;padding:6px 12px;font-weight:600;cursor:pointer;font-size:12.5px">${label}</button>`; };
  const chips=[chip('all','Todas')].concat(turmaKeys().map(tk=>chip(tk,`${esc(tk)} ${esc(NOTAS.turmas[tk].classe)}`))).join(' ');
  const rows=list.map(a=>{ const on=EXUI.sel.includes(a.cod);
    const taken = on ? null : extraDoAluno(a.cod, EXUI.id);
    const alsoIn = on ? extraDoAluno(a.cod, EXUI.id) : null; /* selecionado aqui E também noutra — inconsistência a resolver */
    if(taken){
      return `<label style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-bottom:1px solid #f0f2f6;background:#f7f7f9;opacity:.65;cursor:not-allowed">
        <input type="checkbox" disabled>
        <span style="flex:1;min-width:0"><span style="font-weight:600;font-size:13.5px">${esc(a.nome)}</span>
        <span style="font-size:11.5px;color:#888;margin-left:6px">${a.cod} · ${esc(a.tk)} ${esc(a.classe)}</span>
        <span style="font-size:11px;color:#b35309;display:block;margin-top:2px">já inscrito em: ${esc(taken.nome)}</span></span></label>`;
    }
    const desde=EXUI.desde[a.cod]||e.mesInicio;
    return `<label style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-bottom:1px solid #f0f2f6;cursor:pointer;background:${alsoIn?'#fdf3f2':(on?'#eef7f1':'#fff')}">
      <input type="checkbox" ${on?'checked':''} onchange="exToggleAluno('${a.cod}')">
      <span style="flex:1;min-width:0"><span style="font-weight:600;font-size:13.5px">${esc(a.nome)}</span>
      <span style="font-size:11.5px;color:#888;margin-left:6px">${a.cod} · ${esc(a.tk)} ${esc(a.classe)}</span>
      ${alsoIn?`<span style="font-size:11px;color:#b3261e;font-weight:600;display:block;margin-top:2px">${I.warn} também está em "${esc(alsoIn.nome)}" — desmarque aqui ou lá para resolver</span>`:''}</span>
      ${on?`<span style="display:flex;align-items:center;gap:5px;font-size:11.5px;color:#777;flex-shrink:0" onclick="event.preventDefault()"><span>paga desde:</span><select onchange="exSetDesde('${a.cod}',this.value)" onclick="event.stopPropagation()" style="padding:3px 6px;border:1px solid var(--line);border-radius:6px;font-size:11.5px">${mesesOpts.replace('value="'+desde+'"','value="'+desde+'" selected')}</select></span>`:''}</label>`;
  }).join('') || `<div style="padding:24px;text-align:center;color:#999">Nenhum aluno encontrado.</div>`;
  openModal(`<div class="modal-h"><h3>Alunos · ${esc(e.nome)}</h3><button class="xbtn" onclick="closeModal()">${I.x}</button></div>
  <div class="modal-b">
    <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px">${chips}</div>
    <div class="field" style="margin-bottom:10px"><input id="ex_q" placeholder="Procurar nome ou código…" value="${esc(EXUI.q)}" oninput="EXUI.q=this.value;renderExtraAlunosModal(true)"></div>
    <div style="font-size:12px;color:#888;margin-bottom:8px">Cada aluno só pode estar inscrito numa atividade. Os que já estão noutra aparecem a cinzento. Em <b>"paga desde"</b> escolha o primeiro mês que o aluno deve pagar — útil para inscrições a meio do ano.</div>
    <div style="font-size:12.5px;color:#26324a;font-weight:700;margin-bottom:6px">${EXUI.sel.length} aluno(s) inscrito(s)</div>
    <div class="card" style="padding:0;max-height:46vh;overflow:auto">${rows}</div>
  </div>
  <div class="modal-f"><button class="btn" onclick="closeModal()">Cancelar</button>
  <button class="btn pri" onclick="saveExtraAlunos()">Guardar inscrições</button></div>`, true);
  if(keepFocus){ const el=$('#ex_q'); if(el && document.activeElement!==el && EXUI.q){ el.focus(); el.setSelectionRange(el.value.length,el.value.length); } }
}
function saveExtraAlunos(){ const e=getExtra(EXUI.id); if(!e) return; e.alunos=EXUI.sel.map(cod=>({cod,desde:EXUI.desde[cod]||e.mesInicio})); upd(null,false); closeModal(); toast('Inscrições guardadas ✓'); render(); }


VIEWS.subjects=function(r){
  setSub(DB.subjects.length+' disciplina(s)');
  r.innerHTML=`<div class="vhead" style="display:flex;justify-content:space-between;align-items:flex-end">
    <div><h1>Disciplinas</h1><p>Cada disciplina pertence a uma categoria curricular, que define a cor na legenda dos horários.</p></div>
    <div class="btnrow"><button class="btn" id="editCats">Categorias</button><button class="btn pri" id="addS">${I.plus} Nova disciplina</button></div></div>
    <div class="card"><div class="list">${
      DB.subjects.map(sj=>{const cat=getCat(sj.catId);return `<div class="row"><span class="swatch" style="background:${cat?cat.color:'#999'}"></span>
      <div class="nm">${esc(sj.name)}</div><span class="tag"><span class="d" style="background:${cat?cat.color:'#999'}"></span>${cat?esc(cat.name):'sem categoria'}</span>
      <div class="sp"><button class="btn icon ghost" onclick="editSubj('${sj.id}')">${I.edit}</button><button class="btn icon ghost dng" onclick="delSubj('${sj.id}')">${I.trash}</button></div></div>`;}).join('')||`<div class="empty">${I.subj}<div>Sem disciplinas.</div></div>`
    }</div></div>`;
  $('#addS').onclick=()=>editSubj(null);
  $('#editCats').onclick=editCats;
};
function editSubj(id){
  const sj=id?getSubj(id):{name:'',catId:DB.cats[0].id};
  openModal(`<div class="modal-h"><h3>${id?'Editar':'Nova'} disciplina</h3><button class="xbtn" onclick="closeModal()">${I.x}</button></div>
  <div class="modal-b">${field('Nome','<input type="text" id="m_name" value="'+esc(sj.name)+'" placeholder="ex: Matemática">')}
  ${field('Categoria','<select id="m_cat">'+DB.cats.map(c=>`<option value="${c.id}" ${c.id===sj.catId?'selected':''}>${esc(c.name)}</option>`).join('')+'</select>')}</div>
  <div class="modal-f"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn pri" id="m_save">Guardar</button></div>`);
  $('#m_save').onclick=()=>{const name=$('#m_name').value.trim();if(!name)return toast('Indique o nome',1);
    if(id){sj.name=name;sj.catId=$('#m_cat').value;}else DB.subjects.push({id:uid(),name,catId:$('#m_cat').value});
    upd(null,true);closeModal();toast('Disciplina guardada');};
}
function delSubj(id){const sj=getSubj(id);confirmDel(`Eliminar "${sj.name}"? As atribuições e blocos que a usam serão removidos.`,()=>{DB.subjects=DB.subjects.filter(x=>x.id!==id);DB.assignments=DB.assignments.filter(a=>a.sid!==id);DB.classes.forEach(c=>DAYS.forEach(d=>allSlots().forEach(s=>{const arr=DB.tt[c.id]?.[d]?.[s.id];if(arr)DB.tt[c.id][d][s.id]=arr.filter(e=>e.sid!==id);})));upd(null,true);toast('Eliminada');});}
function editCats(){
  openModal(`<div class="modal-h"><h3>Categorias curriculares</h3><button class="xbtn" onclick="closeModal()">${I.x}</button></div>
  <div class="modal-b"><div id="catList"></div><button class="btn sm" id="addCat" style="margin-top:8px">${I.plus} Adicionar categoria</button></div>
  <div class="modal-f"><button class="btn pri" onclick="closeModal();render()">Concluído</button></div>`,true);
  function paint(){$('#catList').innerHTML=DB.cats.map(c=>`<div class="ent-edit"><input type="color" value="${c.color}" onchange="DB.cats.find(x=>x.id==='${c.id}').color=this.value;persist();" style="width:38px;height:32px;border:1px solid var(--line);border-radius:7px;padding:2px"><input type="text" class="lab" value="${esc(c.name)}" onchange="DB.cats.find(x=>x.id==='${c.id}').name=this.value;persist();" style="border:none;background:transparent"><button class="btn icon ghost dng" onclick="DB.cats=DB.cats.filter(x=>x.id!=='${c.id}');persist();(${paint.toString()})()">${I.trash}</button></div>`).join('');}
  window.__catPaint=paint; paint();
  $('#addCat').onclick=()=>{DB.cats.push({id:uid(),name:'Nova categoria',color:'#64748b'});persist();paint();};
}

