VIEWS.teachers=function(r){
  setSub(DB.teachers.length+' professor(es)');
  const q=(NUI.tq||'').trim().toLowerCase();
  let list=DB.teachers.slice().sort((a,b)=>a.name.localeCompare(b.name));
  if(q) list=list.filter(t=>t.name.toLowerCase().includes(q)||(t.departamento||'').toLowerCase().includes(q)||teacherStats(t.id).subjects.join(' ').toLowerCase().includes(q));
  const cards=list.map(t=>{ const stats=teacherStats(t.id);
    const photo = t.foto ? `<img src="${t.foto}" style="width:38px;height:38px;border-radius:10px;object-fit:cover;flex-shrink:0">` : `<div style="width:38px;height:38px;border-radius:10px;background:#eef1f6;color:#26324a;display:flex;align-items:center;justify-content:center;font-weight:700;flex-shrink:0;font-family:Fraunces,Georgia,serif">${esc(t.name[0]||'?')}</div>`;
    return `<button class="card np-acard" onclick="openProf('${t.id}')" style="display:flex;align-items:center;gap:13px;padding:12px 15px;text-align:left;cursor:pointer;border:none;width:100%">
      ${photo}
      <div style="flex:1;min-width:0"><div style="font-weight:700;font-size:13.5px;color:#26324a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(teacherLabel(t))}</div>
        <div style="font-size:11.5px;color:#888;display:flex;gap:8px;margin-top:2px;align-items:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis"><span>${esc(t.departamento||'Professores')}</span><span>·</span><span style="overflow:hidden;text-overflow:ellipsis">${esc(stats.subjects.join(', ')||'sem disciplinas')}</span></div></div>
      <div style="text-align:right;flex-shrink:0"><div style="font-family:Fraunces,Georgia,serif;font-size:19px;font-weight:700;color:#26324a">${stats.total}</div><div style="font-size:10px;color:#888">aula(s)/sem</div></div></button>`;
  }).join('');
  r.innerHTML=`<div class="vhead" style="display:flex;justify-content:space-between;align-items:flex-end">
    <div><h1>Professores</h1><p>${list.length} registo(s). Clique para abrir a ficha pessoal.</p></div>
    <div style="display:flex;gap:8px">
      <button class="btn pri" onclick="openNovoRegistoElegante('professor')" style="background:var(--brand);color:#fff;border-radius:10px;font-weight:700">✨ Novo Registo</button>
      <button class="btn" id="addT">${I.plus} Novo professor</button>
    </div></div>
    <div class="field" style="max-width:420px;margin-bottom:16px"><input id="tq" placeholder="Procurar por nome, departamento ou disciplina…" value="${esc(NUI.tq)}" oninput="NUI.tq=this.value;render();setTimeout(()=>{const e=$('#tq');if(e){e.focus();e.setSelectionRange(e.value.length,e.value.length);}},0)"></div>
    <div class="grid2" style="grid-template-columns:repeat(2,1fr);gap:10px">${cards||`<div class="empty">${I.teach}<div>Sem professores.</div></div>`}</div>`;
  $('#addT').onclick=()=>editTeacher(null);
};
function teacherStats(tid){
  let total=0; const subjSet=new Set(), clsSet=new Set();
  DB.classes.forEach(c=>DAYS.forEach(d=>allSlots().forEach(s=>{
    const arr=DB.tt[c.id]?.[d]?.[s.id]; if(!arr)return;
    arr.forEach(e=>{if(e.tid===tid){total++;if(e.sid){const sj=getSubj(e.sid);if(sj)subjSet.add(sj.name);}clsSet.add(c.name);}});
  })));
  return {total,subjects:[...subjSet],classes:[...clsSet]};
}

function openProf(id){
  const t=getTeacher(id); if(!t){toast('Professor não encontrado',true);return;}
  const stats=teacherStats(id);
  const val=k=>{const v=t[k]; return v?esc(v):'—';};
  const dataPT=k=>{const v=t[k]; if(!v)return'—'; const d=new Date(v); return isNaN(d)?esc(v):d.toLocaleDateString('pt-PT');};
  const row=(l,v)=>`<tr><td style="padding:6px 10px;font-weight:600;color:#5a6275;width:46%;border-bottom:1px solid #f0f2f6">${l}</td><td style="padding:6px 10px;border-bottom:1px solid #f0f2f6">${v}</td></tr>`;
  const sectionTbl=(grp)=>`<table style="width:100%;border-collapse:collapse"><tbody>${TEACH_FIELDS.filter(f=>f.grp===grp).map(f=>row(f.l, f.t==='date'?dataPT(f.k):val(f.k))).join('')}</tbody></table>`;
  const sectionsHtml = TEACH_SECTIONS.map(s=>`<div class="fc-section"><div class="fc-section-h">${s.t}</div>${sectionTbl(s.grp)}</div>`).join('');
  openModal(`<div class="modal-h" style="background:#26324a;color:#fff"><div style="display:flex;align-items:center;gap:14px;min-width:0">${t.foto?`<img src="${t.foto}" onclick="zoomFoto(this.src)" title="Ampliar foto" style="width:58px;height:77px;object-fit:cover;border-radius:8px;border:2px solid rgba(255,255,255,.3);background:#fff;flex:0 0 auto;cursor:zoom-in">`:`<img src="${PHOTO_PLACEHOLDER}" style="width:58px;height:77px;object-fit:cover;border-radius:8px;border:2px solid rgba(255,255,255,.3);background:#fff;flex:0 0 auto">`}<div style="min-width:0"><div style="font-size:11px;opacity:.7;text-transform:uppercase;letter-spacing:.5px;font-weight:600">Ficha Pessoal do Professor</div>
      <h3 style="color:#fff;font-size:20px;margin:4px 0 0">${esc(teacherLabel(t))}</h3>
      <div style="display:flex;gap:14px;margin-top:8px;font-size:12px;opacity:.9;flex-wrap:wrap"><span>${esc(t.departamento||'Professores')}</span>${t.designacao?`<span>${esc(t.designacao)}</span>`:''}</div></div></div>
    <button class="xbtn" onclick="closeModal()" style="color:#fff">${I.x}</button></div>
  <div class="modal-b">
    <div class="np-stats" style="gap:10px;margin-bottom:14px">
      <div class="card stat"><div class="n">${stats.total}</div><div class="l">Aula(s)/sem</div></div>
      <div class="card stat"><div class="n">${stats.subjects.length}</div><div class="l">Disciplinas</div></div>
      <div class="card stat"><div class="n">${stats.classes.length}</div><div class="l">Turmas</div></div></div>
    ${t.notes?`<div class="fc-section"><div class="fc-section-h">Anotações / Preferências</div><div style="padding:2px 6px;color:#3a4156;font-size:13px">${esc(t.notes)}</div></div>`:''}
    ${sectionsHtml}
  </div>
  <div class="modal-f" style="flex-wrap:wrap;gap:8px">
    <button class="btn pri" onclick="closeModal();editTeacher('${id}')">${I.edit} Editar dados</button>
    <button class="btn" style="border-color:#b8902a;color:#b8902a" onclick="closeModal();UI.teacher='${id}';go('tview')">${I.user} Ver horário completo</button>
    <button class="btn dng" onclick="closeModal();delTeacher('${id}')">${I.trash} Eliminar</button>
  </div>`,true);
}
function editTeacher(id){
  const t=id?getTeacher(id):{title:'Prof.',name:'',notes:'',unav:[]};
  const slots=allSlots();
  const titleSel=`<select id="m_title">`+['','Prof.','Pe.','Dr.','Ir.'].map(x=>`<option value="${x}" ${t.title===x?'selected':''}>${x||'(nenhum)'}</option>`).join('')+`</select>`;
  const pid='ph_tc_'+(id||'new'); initPhoto(pid, t.foto);
  const fieldHtml=f=>{ const v=t[f.k]||'';
    if(f.t==='select') return field(f.l, `<select id="tf_${f.k}"><option value="">—</option>${f.opts.map(o=>`<option ${v===o?'selected':''}>${o}</option>`).join('')}</select>`);
    if(f.t==='textarea') return field(f.l, `<textarea id="tf_${f.k}" rows="2">${esc(v)}</textarea>`);
    return field(f.l, `<input id="tf_${f.k}" type="${f.t}" value="${esc(v)}">`);
  };
  const sectionsHtml = TEACH_SECTIONS.map(s=>{ const fs=TEACH_FIELDS.filter(f=>f.grp===s.grp); if(!fs.length) return '';
    return `<div class="fc-section"><div class="fc-section-h">${s.t}</div><div class="grid2" style="grid-template-columns:1fr 1fr;gap:12px">${fs.map(fieldHtml).join('')}</div></div>`; }).join('');
  openModal(`<div class="modal-h"><h3>${id?'Editar':'Novo'} professor</h3><button class="xbtn" onclick="closeModal()">${I.x}</button></div>
  <div class="modal-b">
    <div class="ficha-photo">${photoField(pid, t.foto)}</div>
    <div class="inline">${field('Título',titleSel)}
    <div style="flex:2.5">${field('Nome completo','<input type="text" id="m_name" value="'+esc(t.name)+'">')}</div></div>
    ${field('Anotações / preferências','<textarea id="m_notes" placeholder="ex: prefere aulas de manhã, livre às quartas…">'+esc(t.notes||'')+'</textarea>')}
    ${sectionsHtml}
    <div class="fc-section"><div class="fc-section-h">Indisponibilidade</div><div style="font-size:12px;color:#888;margin-bottom:8px">Clique nos tempos em que o professor NÃO pode dar aula.</div>
    <div class="tt-wrap" style="box-shadow:none"><table class="tt"><thead><tr><th>Tempo</th>${DAYS.map(d=>`<th>${DAY_SHORT[d]}</th>`).join('')}</tr></thead><tbody>
    ${slots.map(s=>`<tr><td class="tcol">${s.s}</td>${DAYS.map(d=>{const on=(t.unav||[]).some(u=>u.d===d&&u.s===s.id);return `<td class="cell" style="height:auto;min-width:auto;text-align:center;background:${on?'var(--danger-soft)':'#fff'}" data-u="${d}|${s.id}">${on?'✕':''}</td>`;}).join('')}</tr>`).join('')}
    </tbody></table></div></div>
  </div>
  <div class="modal-f"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn pri" id="m_save">Guardar</button></div>`,true);
  let unav=clone(t.unav||[]);
  $('#modal').querySelectorAll('[data-u]').forEach(td=>td.onclick=()=>{const[d,s]=td.dataset.u.split('|');const i=unav.findIndex(u=>u.d===d&&u.s===s);if(i>=0){unav.splice(i,1);td.style.background='#fff';td.textContent='';}else{unav.push({d,s});td.style.background='var(--danger-soft)';td.textContent='✕';}});
  $('#m_save').onclick=()=>{const name=$('#m_name').value.trim();if(!name)return toast('Indique o nome',1);
    const o={title:$('#m_title').value,name,notes:$('#m_notes').value,unav,foto:getPhoto(pid)};
    TEACH_FIELDS.forEach(f=>{ const el=$('#tf_'+f.k); if(el)o[f.k]=el.value.trim(); });
    if(id)Object.assign(t,o);else DB.teachers.push({id:uid(),...o});
    upd(null,true);closeModal();toast('Professor guardado');};
}
function delTeacher(id){const t=getTeacher(id);confirmDel(`Eliminar ${teacherLabel(t)}? Será desassociado dos blocos do horário.`,()=>{DB.teachers=DB.teachers.filter(x=>x.id!==id);DB.assignments=DB.assignments.filter(a=>a.tid!==id);DB.classes.forEach(c=>DAYS.forEach(d=>allSlots().forEach(s=>{const arr=DB.tt[c.id]?.[d]?.[s.id];if(arr)arr.forEach(e=>{if(e.tid===id)e.tid=null;});})));upd(null,true);toast('Eliminado');});}

