  if(targets.length&&UI.expTarget) $('#pz').innerHTML=buildHdoc(UI.expTab,UI.expTarget);
  r.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{ UI.expTab=b.dataset.tab; UI.expTarget=null; render(); });
  const sel=$('#expSel'); if(sel) sel.onchange=e=>{ UI.expTarget=e.target.value; $('#pz').innerHTML=buildHdoc(UI.expTab,UI.expTarget); };
  $('#bPdf')&&($('#bPdf').onclick=exportPDF);
  $('#bPrint')&&($('#bPrint').onclick=exportPrint);
  $('#bXls')&&($('#bXls').onclick=exportXLSX);
