function archRestore(vid){ const v=DB.archive.find(x=>x.id===vid); if(!v)return;
  confirmAct(`Recuperar a versão “${v.label}”? O estado actual de trabalho será substituído. (Se ainda não o guardou, faça-o antes.)`,'Recuperar',()=>{ restoreVersion(vid); buildNav(); go('grid'); toast('Versão recuperada ✓'); }); }
function archOverwrite(vid){ const v=DB.archive.find(x=>x.id===vid); if(!v)return;
  confirmAct(`Gravar o estado actual por cima da versão “${v.label}”? O conteúdo anterior desta versão perde-se.`,'Gravar por cima',()=>{ overwriteVersion(vid); render(); toast('Versão actualizada ✓'); }); }
function archDelete(vid){ const v=DB.archive.find(x=>x.id===vid); if(!v)return;
  confirmDel(`Eliminar a versão “${v.label}” do arquivo?`,()=>{ DB.archive=DB.archive.filter(x=>x.id!==vid); persist(); render(); toast('Versão eliminada'); }); }
function archDuplicate(vid){ const v=DB.archive.find(x=>x.id===vid); if(!v)return;
  openModal(`<div class="modal-h"><h3>Duplicar versão</h3><button class="xbtn" onclick="closeModal()">${I.x}</button></div>
  <div class="modal-b">
    <p style="font-size:13px;color:var(--ink-soft);margin-bottom:12px">Cria uma nova versão a partir de “${esc(v.label)}”. Recupere-a depois para fazer os pequenos ajustes do novo trimestre.</p>
    ${field('Nome da nova versão',`<input type="text" id="dv_label" value="${esc(v.label)} (cópia)">`)}
    ${field('Trimestre',`<select id="dv_tri"><option value="1">1º Trimestre</option><option value="2" selected>2º Trimestre</option><option value="3">3º Trimestre</option><option value="0">Outro</option></select>`)}
  </div>
  <div class="modal-f"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn pri" id="dv_ok">Duplicar</button></div>`);
  $('#dv_ok').onclick=()=>{ duplicateVersion(vid,$('#dv_label').value.trim(),parseInt($('#dv_tri').value)); closeModal(); render(); toast('Versão duplicada ✓'); };
}
function archEdit(vid){ const v=DB.archive.find(x=>x.id===vid); if(!v)return;
  openModal(`<div class="modal-h"><h3>Editar versão</h3><button class="xbtn" onclick="closeModal()">${I.x}</button></div>
  <div class="modal-b">
    ${field('Nome',`<input type="text" id="ev_label" value="${esc(v.label)}">`)}
    <div class="inline">${field('Ano lectivo',`<input type="text" id="ev_year" value="${esc(v.year||'')}">`)}${field('Trimestre',`<select id="ev_tri">${[1,2,3,0].map(t=>`<option value="${t}" ${v.trimester===t?'selected':''}>${TRI[t]}</option>`).join('')}</select>`)}</div>
    ${field('Nota',`<textarea id="ev_note">${esc(v.note||'')}</textarea>`)}
  </div>
  <div class="modal-f"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn pri" id="ev_ok">Guardar</button></div>`);
  $('#ev_ok').onclick=()=>{ v.label=$('#ev_label').value.trim()||v.label; v.year=$('#ev_year').value.trim()||v.year; v.trimester=parseInt($('#ev_tri').value); v.note=$('#ev_note').value.trim(); persist(); closeModal(); render(); toast('Versão actualizada'); };
}

/* ---------- Ferramentas rápidas ---------- */
function swapTeacher(fromTid,toTid,scopeCid){
  let n=0;
  DB.classes.forEach(c=>{ if(scopeCid&&c.id!==scopeCid)return;
    DAYS.forEach(d=>allSlots().forEach(s=>{ const arr=DB.tt[c.id]?.[d]?.[s.id]; if(!arr)return;
      arr.forEach(e=>{ if(e.tid===fromTid){ e.tid=toTid||null; n++; } }); })); });
  DB.assignments.forEach(a=>{ if(a.tid===fromTid && (!scopeCid||a.cid===scopeCid)) a.tid=toTid||null; });
  persist(); return n;
}
function swapCells(cid,dA,sA,dB,sB){
  if(!DB.tt[cid]) return; if(!DB.tt[cid][dA])DB.tt[cid][dA]={}; if(!DB.tt[cid][dB])DB.tt[cid][dB]={};
  const a=DB.tt[cid][dA][sA]||[]; const b=DB.tt[cid][dB][sB]||[];
  DB.tt[cid][dA][sA]=b; DB.tt[cid][dB][sB]=a; persist();
}

/* ============================================================
   VISTA — ARQUIVO
   ============================================================ */
VIEWS.archive=function(r){
  setSub('Histórico por ano e trimestre');
  const arr=DB.archive.slice().sort((a,b)=>b.ts-a.ts);
  const slotOpts=allSlots().map(s=>`<option value="${s.id}">${s.s}–${s.e}</option>`).join('');
  const dayOpts=DAYS.map(d=>`<option value="${d}">${d.charAt(0)+d.slice(1).toLowerCase()}</option>`).join('');
  const teachOpts=DB.teachers.map(t=>`<option value="${t.id}">${esc(teacherLabel(t))}</option>`).join('');
  const clsOpts=DB.classes.map(c=>`<option value="${c.id}">Turma ${esc(c.name)}</option>`).join('');
  const cur=DB.settings.year;
  UI.archOpenYears=UI.archOpenYears||{}; if(!(cur in UI.archOpenYears)) UI.archOpenYears[cur]=true;

  const verRow=(v)=>{ const sm=versionSummary(v); const dt=new Date(v.ts);
    return `<div class="row">
      <div style="min-width:0">
        <div class="nm">${esc(v.label)}</div>
        <div class="meta">${dt.toLocaleString('pt-PT',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})} · ${sm.cls} turma(s) · ${sm.blocks} bloco(s)${v.note?` · <i>${esc(v.note)}</i>`:''}</div>
      </div>
      <div class="sp">
        <button class="btn sm em" onclick="archRestore('${v.id}')">Recuperar</button>
        <button class="btn sm" onclick="archDuplicate('${v.id}')">${I.copy} Duplicar</button>
        <button class="btn sm" onclick="archOverwrite('${v.id}')">Gravar por cima</button>
        <button class="btn icon ghost" onclick="archEdit('${v.id}')">${I.edit}</button>
        <button class="btn icon ghost dng" onclick="archDelete('${v.id}')">${I.trash}</button>
      </div></div>`;
  };
  let years=[...new Set(arr.map(v=>v.year))];
  years.sort((a,b)=>{ if(a===cur)return -1; if(b===cur)return 1; return String(b).localeCompare(String(a),undefined,{numeric:true}); });
  let groups='';
  years.forEach(y=>{ const vers=arr.filter(v=>v.year===y); const open=!!UI.archOpenYears[y];
    groups+=`<div class="yr-folder">
      <div class="yr-h ${open?'open':''}" onclick="archToggleYear('${esc(y)}')">
        <span class="yr-caret">▸</span>${I.archive}<b>Ano Lectivo ${esc(y)}</b>
        ${y===cur?'<span class="yr-badge">ano actual</span>':''}
        <span class="tri-n" style="margin-left:auto">${vers.length}</span>
      </div>`;
    if(open){ groups+=`<div class="yr-body">`;
      [1,2,3,0].forEach(t=>{ const list=vers.filter(v=>v.trimester===t); if(!list.length)return;
        groups+=`<div class="tri-h">${TRI[t]} <span class="tri-n">${list.length}</span></div><div class="list">${list.map(verRow).join('')}</div>`;
      });
      groups+=`</div>`;
    }
    groups+=`</div>`;
  });

  r.innerHTML=`
  <div class="vhead"><h1>Arquivo de versões</h1><p>O horário é um trabalho em evolução. As versões ficam organizadas por <b>ano lectivo</b> e, dentro de cada ano, por trimestre. O ano actual está aberto; os anteriores ficam em pastas, sempre acessíveis.</p></div>

  <div class="card" style="margin-bottom:18px">
    <div class="card-h"><h3>Ano lectivo ${esc(DB.settings.year)}</h3><div style="display:flex;gap:8px"><button class="btn" id="aNewYear">${I.archive} Novo ano lectivo</button><button class="btn em" id="aSave">${I.archive} Guardar versão</button></div></div>
    <div class="help" style="margin:14px">${I.info}<div>“Guardar versão” tira uma fotografia do estado actual. Fluxo sugerido: guarde o <b>1º trimestre</b>; para o 2º, <b>duplique</b> essa versão, <b>recupere-a</b>, faça os retoques e guarde. No fim do ano, use <b>“Novo ano lectivo”</b> — o ano actual passa para a sua pasta e começa um ano limpo.</div></div>
  </div>

  <div class="card" style="margin-bottom:18px">
    <div class="card-h"><h3>Versões arquivadas</h3><span class="sub">${DB.archive.length} no total</span></div>
    ${arr.length?groups:`<div class="empty">${I.archive}<div>Ainda não há versões. Componha o horário e guarde a primeira.</div></div>`}
  </div>

  <div class="card">
    <div class="card-h"><h3>Ferramentas rápidas</h3><span class="sub">resolver problemas pontuais</span></div>
    <div style="padding:16px 22px;display:flex;flex-direction:column;gap:22px">
      <div>
        <div class="qt-t">${I.teach} Substituir um professor por outro</div>
        <div class="qt-row">
          <select id="qt_from">${teachOpts}</select>
          <span class="qt-ar">→</span>
          <select id="qt_to"><option value="">(sem professor)</option>${teachOpts}</select>
          <select id="qt_scope" style="min-width:150px"><option value="">Em todas as turmas</option>${clsOpts}</select>
          <button class="btn pri" id="qt_go">Substituir</button>
        </div>
        <div class="hint" style="margin-top:6px;font-size:11.5px;color:var(--ink-faint)">Troca o professor em todas as aulas correspondentes (e nas atribuições). Útil quando um docente sai ou é substituído.</div>
      </div>
      <div style="border-top:1px solid var(--line-2);padding-top:18px">
        <div class="qt-t">${I.grid} Trocar duas aulas de lugar</div>
        <div class="qt-row">
          <select id="qc_cls">${clsOpts}</select>
          <span style="font-size:12px;color:var(--ink-soft)">Aula A:</span>
          <select id="qc_dA">${dayOpts}</select><select id="qc_sA">${slotOpts}</select>
          <span class="qt-ar">⇄</span>
          <span style="font-size:12px;color:var(--ink-soft)">Aula B:</span>
          <select id="qc_dB">${dayOpts}</select><select id="qc_sB">${slotOpts}</select>
          <button class="btn pri" id="qc_go">Trocar</button>
        </div>
        <div class="hint" style="margin-top:6px;font-size:11.5px;color:var(--ink-faint)">Inverte o conteúdo de dois tempos da mesma turma. Para substituir uma disciplina/professor num tempo específico, use o editor de horários.</div>
      </div>
    </div>
  </div>`;

  $('#aSave').onclick=saveVersionDialog;
  $('#aNewYear').onclick=startNewYearDialog;
  $('#qt_go').onclick=()=>{ const f=$('#qt_from').value, t=$('#qt_to').value, sc=$('#qt_scope').value||null;
    if(f===t){ toast('Escolha professores diferentes',true); return; }
    const tn=t?teacherLabel(getTeacher(t)):'(sem professor)';
    confirmAct(`Substituir ${teacherLabel(getTeacher(f))} por ${tn}${sc?' na turma '+getClass(sc).name:' em todas as turmas'}?`,'Substituir',()=>{ const n=swapTeacher(f,t,sc); render(); toast(n?`${n} aula(s) actualizada(s)`:'Nenhuma aula afectada',!n); }); };
  $('#qc_go').onclick=()=>{ const cid=$('#qc_cls').value, dA=$('#qc_dA').value, sA=$('#qc_sA').value, dB=$('#qc_dB').value, sB=$('#qc_sB').value;
    if(dA===dB&&sA===sB){ toast('Escolha dois tempos diferentes',true); return; }
    swapCells(cid,dA,sA,dB,sB); toast('Aulas trocadas ✓'); };
};

/* ============================================================
   ARRANQUE DA APLICAÇÃO
   ============================================================ */
function ensureTeacherAssignmentsFix(db){
  if(!db) return;
  const filSubjIds = (db.subjects || []).filter(s => ['Filosofia','Intr. à Filosofia'].includes(s.name)).map(s => s.id);
  const itaSubj = (db.subjects || []).find(s => s.name === 'Italiano');

  if (Array.isArray(db.assignments)) {
    db.assignments.forEach(a => {
      if (a.sid && filSubjIds.includes(a.sid) && a.tid !== 'p114') a.tid = 'p114';
      if (itaSubj && a.sid === itaSubj.id && a.tid !== 'p104') a.tid = 'p104';
    });
  }

  if (db.tt && typeof db.tt === 'object') {
    Object.keys(db.tt).forEach(cid => {
      const clsDays = db.tt[cid];
      if (!clsDays) return;
      Object.keys(clsDays).forEach(d => {
        const slots = clsDays[d];
        if (!slots) return;
        Object.keys(slots).forEach(sid => {
          const arr = slots[sid];
          if (Array.isArray(arr)) {
            arr.forEach(entry => {
              if (entry.sid && filSubjIds.includes(entry.sid) && entry.tid !== 'p114') entry.tid = 'p114';
              if (itaSubj && entry.sid === itaSubj.id && entry.tid !== 'p104') entry.tid = 'p104';
            });
          }
        });
      });
    });
  }

  if (Array.isArray(db.teachers)) {
    const maver = db.teachers.find(t => t.id === 'p114' || (t.name || '').includes('Maver'));
    if (maver) maver.disciplinas = 'Filosofia, Intr. à Filosofia, Ética e Cidadania';
    const fausto = db.teachers.find(t => t.id === 'p104' || (t.name || '').includes('Fausto'));
    if (fausto) fausto.disciplinas = 'Italiano';
  }
}

(async function init(){
  const saved = await loadDB();
  DB = (saved && saved.settings && saved.classes && saved.tt) ? saved : seed();
  ensureSchema(DB);
  ensureUsers(DB);
  ensureTeacherAssignmentsFix(DB);
  const seeded=mergeAnagSeed();
  const fseeded=mergeFotosSeed();
  const pseeded=mergeAnagPatch();
  if(!saved) await persist(); else if(seeded||fseeded||pseeded) await persist();
  try{ applyT1Overrides(); }catch(e){}
  await restoreBackupHandle();

  if (!loadSession()) {
    if (DB && Array.isArray(DB.users) && DB.users.length > 0) {
      AUTH_USER = DB.users.find(u => u.id === 'direcao') || DB.users[0];
      PREVIEW_ROLE = AUTH_USER.role;
      saveSession(AUTH_USER.id);
    }
  }

  const app=$('#app'); if(app) app.style.display='';
  buildNav();
  go('dash');
})();



