function mergeAnagSeed(){
  ensureAnag();
  if(DB._anagSeedV1) return;            /* corre só uma vez */
  let n=0;
  for(const cod in ANAG_SEED){
    const src=ANAG_SEED[cod];
    DB.anag[cod]=DB.anag[cod]||{};
    for(const k in src){
      if(DB.anag[cod][k]==null||String(DB.anag[cod][k]).trim()===''){ DB.anag[cod][k]=src[k]; n++; }
    }
  }
  DB._anagSeedV1=true;
  return n;
}

