function zoomFoto(src){
  if(!src || src.indexOf('image/svg')>=0) return;
  const ov=document.createElement('div');
  ov.style.cssText='position:fixed;inset:0;z-index:99999;background:rgba(15,20,30,.86);display:flex;align-items:center;justify-content:center;padding:24px;cursor:zoom-out';
  const img=document.createElement('img');
  img.src=src;
  img.style.cssText='max-width:92vw;max-height:92vh;border-radius:12px;box-shadow:0 14px 50px rgba(0,0,0,.55);object-fit:contain;background:#fff';
  ov.appendChild(img);
  const close=()=>{ ov.remove(); document.removeEventListener('keydown',onKey); };
  function onKey(e){ if(e.key==='Escape') close(); }
  ov.addEventListener('click',close);
  document.addEventListener('keydown',onKey);
  document.body.appendChild(ov);
}
function getAnag(cod){ ensureAnag(); return DB.anag[cod] || {}; }
function setAnag(cod, data){ ensureAnag(); DB.anag[cod] = Object.assign({}, DB.anag[cod], data); persist(); }
/* find a student across turmas by código */
function findAluno(cod){ for(const tk in NOTAS.turmas){ const t=NOTAS.turmas[tk]; if(t.roster[cod]) return {tk,t,a:t.roster[cod]}; } return null; }
function anagFilled(cod){ const a=getAnag(cod); return ANAG_FIELDS.filter(f=>a[f.k]&&String(a[f.k]).trim()!=='').length; }

const AUI = { turma:'all', q:'' };

function gerarCartoesAnag(){
  const q=AUI.q.trim().toLowerCase(); const codes=[];
  turmaKeys().forEach(tk=>{ if(AUI.turma!=='all'&&AUI.turma!==tk) return; const t=NOTAS.turmas[tk];
    Object.keys(t.roster).forEach(cod=>{ const nm=t.roster[cod].nome;
      if(!q||nm.toLowerCase().includes(q)||String(cod).toLowerCase().includes(q)) codes.push(cod); }); });
  if(!codes.length){ toast('Nenhum aluno na seleção',true); return; }
  printCartoes(codes);
}
VIEWS.anag = function(r){
  setSub('Ficha cadastral dos alunos');
  ensureAnag(); ensureInscr();
  const all=[];
  turmaKeys().map(k=>[k,NOTAS.turmas[k]]).forEach(([tk,t])=>Object.keys(t.roster).forEach(cod=>all.push({tk,cod,...t.roster[cod],sec:t.sec[cod],classe:`${t.classe} T${t.turma}`})));
  all.sort((a,b)=>a.nome.localeCompare(b.nome));
  const q=AUI.q.trim().toLowerCase();
  const semCt = s => !((getAnag(s.cod).encContacto||'').trim());
  let list = AUI.turma==='semct' ? all.filter(semCt) : all.filter(s=>AUI.turma==='all'||s.tk===AUI.turma);
  if(q) list=list.filter(s=>s.nome.toLowerCase().includes(q)||String(s.cod).toLowerCase().includes(q));
  const preCount=DB.inscricoes.length;
  const semCtCount=all.filter(semCt).length;
  const tabs=[['all','Todas']].concat(turmaKeys().map(k=>[k,`${NOTAS.turmas[k].classe} T${NOTAS.turmas[k].turma}`]))
    .map(([k,l])=>`<button class="btn sm ${AUI.turma===k?'pri':''}" onclick="AUI.turma='${k}';render()">${l}</button>`).join('')
    + `<button class="btn sm ${AUI.turma==='pre'?'pri':''}" onclick="AUI.turma='pre';render()" style="${AUI.turma==='pre'?'':'border-color:#d9b85a;color:#8a6d1a'}">Inscrições / Novos${preCount?` (${preCount})`:''}</button>`
    + `<button class="btn sm ${AUI.turma==='semct'?'pri':''}" onclick="AUI.turma='semct';render()" style="${AUI.turma==='semct'?'':'border-color:#e6b3ae;color:#b3261e'}" title="Alunos sem telemóvel do encarregado — necessário para os avisos por SMS">Sem contacto${semCtCount?` (${semCtCount})`:''}</button>`;
  const totalFields=ANAG_FIELDS.length;
  if(AUI.turma==='pre'){
    r.innerHTML=`<div class="vhead"><h1>Inscrições — Novos Alunos</h1><p>Pré-inscrição de novos alunos e integrações. Os dados são guardados neste dispositivo.</p></div>
    <div class="sp" style="margin-bottom:14px;gap:8px;flex-wrap:wrap"><div style="display:flex;gap:8px;flex-wrap:wrap">${tabs}</div></div>
    <div class="field" style="max-width:380px;margin-bottom:14px"><input id="aq" placeholder="Procurar nome…" value="${esc(AUI.q)}" oninput="AUI.q=this.value;render();setTimeout(()=>{const e=document.getElementById('aq');if(e){e.focus();e.setSelectionRange(e.value.length,e.value.length);}},0)"></div>
    ${renderInscrTable()}`;
    return;
  }
  const rows=list.map((s,i)=>{ const f=anagFilled(s.cod); const pct=Math.round(f/totalFields*100);
    const a=getAnag(s.cod);
    return `<tr class="np-row" style="cursor:pointer;background:${i%2?'#fbf8f1':'#fff'}" onclick="openFicha('${s.cod}')">
      <td style="padding:8px 12px;font-weight:600;color:#26324a">${esc(s.nome)}</td>
      <td style="padding:8px;text-align:center;color:#666">${s.cod}</td>
      <td style="padding:8px;text-align:center">${s.classe}${s.tk!=='10-2'?` · ${s.sec}`:''}</td>
      <td style="padding:8px;color:#666">${esc(a.nascData||'—')}</td>
      <td style="padding:8px;color:#666">${a.encContacto?esc(a.encContacto):'<span style="color:#b3261e;font-weight:600">em falta</span>'}</td>
      <td style="padding:8px;text-align:center">${a.estado?`<span class="tag">${esc(a.estado)}</span>`:'<span style="color:#bbb">—</span>'}</td>
      <td style="padding:8px;width:120px"><div style="display:flex;align-items:center;gap:6px"><div style="flex:1;height:6px;background:#eee;border-radius:99px;overflow:hidden"><div style="height:100%;width:${pct}%;background:${pct===100?'#0e7d52':pct>0?'#b8902a':'#ccc'}"></div></div><span style="font-size:10px;color:#888">${f}/${totalFields}</span></div></td></tr>`;
  }).join('');
  r.innerHTML=`<div class="vhead"><h1>Anagrafe — Fichas dos Alunos</h1><p>Dados anagráficos e escolares de cada aluno. Clique numa linha para abrir e editar a ficha. Os dados são guardados neste dispositivo.</p></div>
  <div style="display:flex; flex-wrap:wrap; justify-content:space-between; align-items:flex-start; gap:16px; margin-bottom:24px;">
    <div style="display:flex; flex-direction:column; gap:12px; flex:1; min-width:320px;">
      <div class="field" style="margin-bottom:0; width:100%; max-width:400px;">
        <div style="position:relative;">
          <span style="position:absolute; left:12px; top:50%; transform:translateY(-50%); color:var(--ink-soft); pointer-events:none;">
            <svg width="15" height="15" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
          </span>
          <input id="aq" style="padding-left:36px; border-radius:20px; box-shadow:var(--shadow-sm)" placeholder="Procurar aluno por nome ou código…" value="${esc(AUI.q)}" oninput="AUI.q=this.value;render();setTimeout(()=>{const e=document.getElementById('aq');if(e){e.focus();e.setSelectionRange(e.value.length,e.value.length);}},0)">
        </div>
      </div>
      <div style="display:flex; gap:6px; flex-wrap:wrap;">${tabs}</div>
    </div>
    <div style="display:flex; gap:8px; flex-wrap:wrap; align-items:center; padding-top:4px;">
      <button class="btn pri sm" onclick="openNovoRegistoElegante('aluno')" style="background:var(--brand);color:#fff;border-radius:10px;font-weight:700">✨ Novo Registo</button>
      <button class="btn ghost sm" onclick="anagTemplate()">${I.exp} Modelo Excel</button>
      <button class="btn ghost sm" onclick="document.getElementById('anagImp').click()">${I.exp} Importar</button>
      <input type="file" id="anagImp" accept=".xlsx,.xls,.csv" style="display:none" onchange="anagImport(this.files[0])">
      <div style="width:1px; height:24px; background:var(--line); margin:0 4px;"></div>
      <button class="btn sm" onclick="gerarCartoesAnag()">${I.idcard} Cartões</button>
      <button class="btn sm em" onclick="anagExport()">${I.exp} Exportar</button>
    </div>
  </div>
  <div class="card" style="overflow-x:auto;padding:0"><table style="border-collapse:collapse;width:100%;font-size:13px">
    <thead><tr style="background:#26324a;color:#fff"><th style="padding:9px 12px;text-align:left">Nome</th><th style="padding:9px 8px">Código</th><th style="padding:9px 8px">Turma</th><th style="padding:9px 8px;text-align:left">Nascimento</th><th style="padding:9px 8px;text-align:left">Contacto Enc.</th><th style="padding:9px 8px">Estado</th><th style="padding:9px 8px">Preenchido</th></tr></thead>
    <tbody>${rows||'<tr><td colspan="7" style="padding:30px;text-align:center;color:#999">Nenhum aluno encontrado.</td></tr>'}</tbody></table></div>
  <p style="font-size:11.5px;color:#888;margin-top:10px">${list.length} aluno(s). A barra mostra quantos campos da ficha já estão preenchidos.</p>`;
  list.forEach&&r.querySelectorAll('tbody td').forEach(td=>td.style.borderBottom='1px solid #ece5d6');
};

/* ============================================================
   FOTO (provisória) — alunos, docentes e CTA
   Guardada como data:URI (JPEG ~480×640) dentro do próprio
   registo, persistida em IndexedDB junto com os outros dados.
   ============================================================ */
const PHOTO_PLACEHOLDER = "data:image/svg+xml;base64,";
const PHOTO_TMP = {};
function initPhoto(pid, uri){ PHOTO_TMP[pid] = uri || ''; }
function getPhoto(pid){ return PHOTO_TMP[pid] || ''; }
function loadPhoto(pid, file){ _readPhoto(file, uri=>{ PHOTO_TMP[pid]=uri; const im=document.getElementById(pid+'_img'); if(im) im.src=uri; }); }
function clearPhoto(pid){ PHOTO_TMP[pid]=''; const im=document.getElementById(pid+'_img'); if(im) im.src=PHOTO_PLACEHOLDER; }
function _readPhoto(file, cb){
  if(!file) return;
  if(!/^image\//.test(file.type)){ toast('Escolha um ficheiro de imagem',true); return; }
  const fr=new FileReader();
  fr.onload=e=>{ const img=new Image();
    img.onload=()=>{ const TW=480, TH=640, tar=TW/TH;
      const cv=document.createElement('canvas'); cv.width=TW; cv.height=TH;
      const ctx=cv.getContext('2d'); ctx.fillStyle='#fff'; ctx.fillRect(0,0,TW,TH);
      const ar=img.width/img.height; let sw,sh,sx,sy;
      if(ar>tar){ sh=img.height; sw=sh*tar; sx=(img.width-sw)/2; sy=0; }
      else { sw=img.width; sh=sw/tar; sx=0; sy=(img.height-sh)/2; }
      ctx.drawImage(img,sx,sy,sw,sh,0,0,TW,TH);
      cb(cv.toDataURL('image/jpeg',0.82));
    };
    img.onerror=()=>toast('Imagem inválida',true);
    img.src=e.target.result;
  };
  fr.readAsDataURL(file);
}
function photoField(pid, uri){
  const has = uri && uri.length>40;
  return `<div style="display:flex;flex-direction:column;align-items:center;gap:7px">
    <div id="${pid}_box" title="Clique para carregar a foto" onclick="document.getElementById('${pid}_inp').click()" style="cursor:pointer;width:120px;height:160px;border-radius:10px;overflow:hidden;border:2px solid #e0d8c6;background:#eef1f6;box-shadow:0 1px 3px rgba(0,0,0,.10)">
      <img id="${pid}_img" src="${has?uri:PHOTO_PLACEHOLDER}" style="width:100%;height:100%;object-fit:cover;display:block">
    </div>
    <div style="display:flex;gap:6px">
      <button type="button" class="btn sm" onclick="document.getElementById('${pid}_inp').click()">Carregar</button>
      <button type="button" class="btn sm" onclick="clearPhoto('${pid}')">Remover</button>
    </div>
    <input type="file" id="${pid}_inp" accept="image/*" capture="environment" style="display:none" onchange="loadPhoto('${pid}',this.files[0])">
    <div style="font-size:10.5px;color:#9aa0aa">Foto 3×4 (JPEG)</div>
  </div>`;
}

