function emConstrucao(titulo, desc, pontos){
  setSub('Nova organização');
  return `<div class="vhead"><h1>${titulo}</h1><p>${desc}</p></div>
  <div class="card" style="max-width:680px;padding:22px">
    <span style="display:inline-block;background:#f5edd7;color:#8a6d1a;font-size:11px;font-weight:700;padding:3px 10px;border-radius:999px;letter-spacing:.5px">A DESENVOLVER</span>
    <p style="margin:14px 0 10px;color:#444">Esta secção faz parte da nova organização da plataforma. O seu lugar já está definido; o conteúdo será construído a seguir.</p>
    ${pontos&&pontos.length?`<div style="font-size:13px;color:#555"><b>Vai conter:</b><ul style="margin:8px 0 0;padding-left:18px;line-height:1.9">${pontos.map(p=>`<li>${p}</li>`).join('')}</ul></div>`:''}
  </div>`;
}
/* ============================================================
   CTA — Corpo Técnico-Administrativo (pessoal não docente)
   ============================================================ */
